import{_ as r,o as a,c as n,ag as o}from"./chunks/framework.BJFNwp4n.js";const m=JSON.parse('{"title":"Module 5：旅行","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/modules/maltese-module5-analysis.md","filePath":"zh/more/maltese/modules/maltese-module5-analysis.md"}'),s={name:"zh/more/maltese/modules/maltese-module5-analysis.md"};function i(g,t,d,e,l,b){return a(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794416186000"},[...t[0]||(t[0]=[o('<h1 id="module-5-旅行" tabindex="-1">Module 5：旅行 <a class="header-anchor" href="#module-5-旅行" aria-label="Permalink to &quot;Module 5：旅行&quot;">​</a></h1><h2 id="封面" tabindex="-1">封面 <a class="header-anchor" href="#封面" aria-label="Permalink to &quot;封面&quot;">​</a></h2><h3 id="封面-1" tabindex="-1">封面 <a class="header-anchor" href="#封面-1" aria-label="Permalink to &quot;封面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原文</th><th>中文与词语解析</th></tr></thead><tbody><tr><td>MQF 2 – Maltese Language and Cultural Orientation for Foreigners</td><td>马耳他资格框架第 2 级：面向外国人的马耳他语与文化入门。<br><strong>MQF 2</strong>：资格级别，不是“第二模块”。<br><strong>Maltese Language</strong>：马耳他语。<br><strong>Cultural Orientation</strong>：文化导向／入门。<br><strong>for Foreigners</strong>：面向外国人。</td></tr><tr><td>Module 5 / Is-safar</td><td>第五模块：旅行。<br><strong>Module 5</strong>：模块 5。<br><strong>is-</strong>：定冠词 il- 在 s 前同化。<br><strong>safar</strong>：旅行、出国旅行，名词。</td></tr></tbody></table><hr><h2 id="_1-阅读短文逐句解析" tabindex="-1">1 阅读短文逐句解析 <a class="header-anchor" href="#_1-阅读短文逐句解析" aria-label="Permalink to &quot;1 阅读短文逐句解析&quot;">​</a></h2><h3 id="逐句阅读" tabindex="-1">逐句阅读 <a class="header-anchor" href="#逐句阅读" aria-label="Permalink to &quot;逐句阅读&quot;">​</a></h3><p><code>Il-Qari – Aqra din is-silta u wara wieġeb il-mistoqsijiet</code>：阅读——读这段文章，然后回答问题。<strong>Aqra</strong>：读；<strong>din is-silta</strong>：这段文章；<strong>u wara</strong>：然后；<strong>wieġeb</strong>：回答；<strong>il-mistoqsijiet</strong>：问题。</p><table tabindex="0"><thead><tr><th>原句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>F’April li għadda, jien u l-għarus tiegħi sifirna sal-Italja.</td><td>去年／刚过去的四月，我和未婚夫去了意大利旅行。<br><strong>F’April</strong>：在四月。<br><strong>li għadda</strong>：过去的，修饰 April。<br><strong>jien</strong>：我。<br><strong>u</strong>：和。<br><strong>l-għarus tiegħi</strong>：我的男友／未婚夫。<br><strong>sifirna</strong>：我们旅行了，过去时。<br><strong>sal-Italja</strong>：到意大利，sa + 定冠词。</td></tr><tr><td>Malli wasalna l-ajruport ħadt qatgħa għax ħsibt li kelli l-bagalja itqal milli suppost!</td><td>刚到机场时我吓了一跳，因为我以为行李超重了。<br><strong>Malli</strong>：一……就。<br><strong>wasalna</strong>：我们到达。<br><strong>l-ajruport</strong>：机场，此处表示到机场。<br><strong>ħadt qatgħa</strong>：我吓了一跳，固定表达。<br><strong>għax</strong>：因为。<br><strong>ħsibt</strong>：我以为。<br><strong>li</strong>：引出从句。<br><strong>kelli</strong>：我有／当时有。<br><strong>l-bagalja</strong>：行李箱。<br><strong>itqal</strong>：更重。<br><strong>milli suppost</strong>：比规定／应有的程度。</td></tr><tr><td>Iżda mbagħad ikkonfermajna li kollox kien sew.</td><td>不过后来我们确认一切正常。<br><strong>Iżda</strong>：但是。<br><strong>mbagħad</strong>：后来。<br><strong>ikkonfermajna</strong>：我们确认了。<br><strong>li</strong>：……这件事。<br><strong>kollox</strong>：一切。<br><strong>kien</strong>：当时是。<br><strong>sew</strong>：正常、妥当。</td></tr><tr><td>Kif irfisna fuq l-art Taljana, mill-ewwel ħassejna lit-temp kien iktar frisk minn dak li konna ħallejna warajna Malta.</td><td>一踏上意大利土地，我们立即觉得天气比离开马耳他时凉爽。原文 lit-temp 宜断成 li t-temp。<br><strong>Kif</strong>：当……时／一……就。<br><strong>irfisna</strong>：我们踏上。<br><strong>fuq</strong>：在……上。<br><strong>l-art Taljana</strong>：意大利土地，Taljana 阴性配 art。<br><strong>mill-ewwel</strong>：立即。<br><strong>ħassejna</strong>：我们感觉到。<br><strong>li t-temp</strong>：天气……。<br><strong>kien iktar frisk</strong>：当时更凉爽。<br><strong>minn dak</strong>：比那个，dak 指先前天气。<br><strong>li konna ħallejna</strong>：我们此前留下的。<br><strong>warajna</strong>：在我们身后。<br><strong>Malta</strong>：在马耳他。</td></tr><tr><td>Fl-ewwel ġurnata żorna Pisa, imbagħad Firenze kif ukoll Cinque Terre; xi ġmiel kien hemm!</td><td>第一天我们游览比萨，之后佛罗伦萨以及五渔村；那里真美！<br><strong>Fl-ewwel ġurnata</strong>：在第一天。<br><strong>żorna</strong>：我们参观了。<br><strong>Pisa / Firenze / Cinque Terre</strong>：比萨／佛罗伦萨／五渔村。<br><strong>imbagħad</strong>：然后。<br><strong>kif ukoll</strong>：也、以及。<br><strong>xi ġmiel</strong>：多美啊，感叹。<br><strong>kien hemm</strong>：那里有／当时呈现。</td></tr><tr><td>L-iktar ħaġa li laqtitni kien il-Katidral ta’ Firenze daqskemm hu kbir!</td><td>最令我印象深刻的是佛罗伦萨大教堂，因为它实在太宏大！<br><strong>L-iktar ħaġa</strong>：最……的事物。<br><strong>li laqtitni</strong>：使我印象深刻的，-ni＝我。<br><strong>kien</strong>：是。<br><strong>il-Katidral</strong>：大教堂。<br><strong>ta’ Firenze</strong>：佛罗伦萨的。<br><strong>daqskemm</strong>：由于如此／何等程度。<br><strong>hu kbir</strong>：它很大。</td></tr><tr><td>Minkejja dan, l-isbaħ veduti kienu ta’ Cinque Terre, għax hemm ħafna natura, ħdura u paċi.</td><td>尽管如此，最美的风景在五渔村，因为那里有丰富的自然景观、绿意与宁静。<br><strong>Minkejja dan</strong>：尽管如此。<br><strong>l-isbaħ veduti</strong>：最美的景色。<br><strong>kienu</strong>：当时是，复数。<br><strong>ta’ Cinque Terre</strong>：五渔村的。<br><strong>għax</strong>：因为。<br><strong>hemm</strong>：那里有。<br><strong>ħafna</strong>：很多。<br><strong>natura</strong>：自然。<br><strong>ħdura</strong>：绿色植被、绿意。<br><strong>u paċi</strong>：与宁静。</td></tr><tr><td>Imxejna ħafna, speċjalment bejn raħal u ieħor u b’hekk gawdejna l-inħawi aħjar.</td><td>我们走了很多路，特别是在村落之间，因此更充分地欣赏了周边。<br><strong>Imxejna</strong>：我们步行了。<br><strong>ħafna</strong>：很多。<br><strong>speċjalment</strong>：特别。<br><strong>bejn</strong>：在……之间。<br><strong>raħal u ieħor</strong>：一个村子和另一个村子。<br><strong>u b’hekk</strong>：并因此。<br><strong>gawdejna</strong>：我们享受／欣赏了。<br><strong>l-inħawi</strong>：周围地区。<br><strong>aħjar</strong>：更好、更充分。</td></tr><tr><td>L-ikel Taljan ukoll huwa mill-aqwa.</td><td>意大利食物也非常出色。<br><strong>L-ikel Taljan</strong>：意大利食物。<br><strong>ukoll</strong>：也。<br><strong>huwa</strong>：是。<br><strong>mill-aqwa</strong>：最出色之列、非常棒，固定表达。</td></tr><tr><td>L-itjeb ikla li ħadna kienet minn Firenze, li kienet tikkonsistni f’taħlita ta’ ikel differenti; għaġin, laħam u ħut!</td><td>最好吃的一餐来自佛罗伦萨，由不同食物组成：意面、肉和鱼。tikkonsistni 宜为 tikkonsisti。<br><strong>L-itjeb ikla</strong>：最好的一餐。<br><strong>li ħadna</strong>：我们吃过的；ħadna 本义“我们拿了”。<br><strong>kienet</strong>：当时是，阴性配 ikla。<br><strong>minn Firenze</strong>：来自佛罗伦萨。<br><strong>li kienet tikkonsisti</strong>：它当时由……组成。<br><strong>f’taħlita</strong>：在一种混合／组合中。<br><strong>ta’ ikel differenti</strong>：不同食物的。<br><strong>għaġin</strong>：意面。<br><strong>laħam</strong>：肉。<br><strong>u ħut</strong>：和鱼。</td></tr><tr><td>Wara dan kollu, dejjem ħallejna spazju għall-ħelu speċjalment għall-kantucci jew għal xi ġelat!</td><td>吃了这些之后，我们总还留着肚子吃甜食，尤其是 cantucci 饼干或冰淇淋！<br><strong>Wara dan kollu</strong>：在所有这些之后。<br><strong>dejjem</strong>：总是。<br><strong>ħallejna</strong>：我们留下。<br><strong>spazju</strong>：空间，这里指胃口。<br><strong>għall-ħelu</strong>：给甜食。<br><strong>speċjalment</strong>：尤其。<br><strong>għall-kantucci</strong>：给 cantucci，意大利杏仁脆饼。<br><strong>jew</strong>：或者。<br><strong>għal xi ġelat</strong>：给一些冰淇淋。</td></tr></tbody></table><h3 id="六道阅读题" tabindex="-1">六道阅读题 <a class="header-anchor" href="#六道阅读题" aria-label="Permalink to &quot;六道阅读题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题与完整参考回答</th><th>中文与重点拆解</th></tr></thead><tbody><tr><td>Meta siefru? — Is-safra kienet f’April li għadda.</td><td>他们什么时候旅行？——这次旅行在上一个四月。<br><strong>Meta</strong>：何时。<br><strong>siefru</strong>：原题“他们旅行了”。<br><strong>Is-safra</strong>：这次旅行。<br><strong>kienet</strong>：当时是。<br><strong>f’April</strong>：在四月。<br><strong>li għadda</strong>：过去的。</td></tr><tr><td>Fejn marru? — Marru l-Italja u żaru Pisa, Firenze u Cinque Terre.</td><td>去哪里？——去了意大利，游览比萨、佛罗伦萨和五渔村。<br><strong>Fejn</strong>：哪里。<br><strong>marru</strong>：他们去了。<br><strong>l-Italja</strong>：意大利。<br><strong>u żaru</strong>：并参观。<br><strong>Pisa, Firenze u Cinque Terre</strong>：三处地名。</td></tr><tr><td>X’inhi l-iktar ħaġa li laqtitha u għaliex? — L-iktar li laqatha kien il-Katidral ta’ Firenze għax huwa kbir ħafna.</td><td>最打动她的是什么，为什么？——佛罗伦萨大教堂，因为很宏大。<br><strong>X’inhi</strong>：是什么，x’ + hi。<br><strong>l-iktar ħaġa</strong>：最……的事物。<br><strong>li laqtitha</strong>：给她印象深刻的。<br><strong>u għaliex</strong>：并且为什么。<br><strong>L-iktar li laqatha</strong>：最打动她的。<br><strong>kien il-Katidral ta’ Firenze</strong>：是佛罗伦萨大教堂。<br><strong>għax huwa kbir ħafna</strong>：因为它非常大。</td></tr><tr><td>Fejn raw l-isbaħ veduti? — Raw l-isbaħ veduti f’Cinque Terre, fejn hemm ħafna ħdura u paċi.</td><td>哪里景色最美？——五渔村，那里绿意丰富而宁静。<br><strong>raw</strong>：他们看见。<br><strong>l-isbaħ veduti</strong>：最美的景色。<br><strong>f’Cinque Terre</strong>：在五渔村。<br><strong>fejn</strong>：那里。<br><strong>hemm ħafna ħdura u paċi</strong>：有很多绿意与宁静。</td></tr><tr><td>Liema kienet l-itjeb ikla li ħadu? — L-itjeb ikla kienet f’Firenze u kienet tinkludi għaġin, laħam u ħut.</td><td>哪一餐最好？——在佛罗伦萨的一餐，含意面、肉和鱼。<br><strong>Liema</strong>：哪一个。<br><strong>kienet l-itjeb ikla</strong>：是最好的一餐。<br><strong>li ħadu</strong>：他们吃过的。<br><strong>f’Firenze</strong>：在佛罗伦萨。<br><strong>u kienet tinkludi</strong>：并且包括。<br><strong>għaġin, laħam u ħut</strong>：意面、肉和鱼。</td></tr><tr><td>Semmi 2 tipi ta’ ħelu li hemm fis-silta. — Fis-silta jissemmew il-kantucci u l-ġelat.</td><td>说出文中两种甜食。——cantucci 和冰淇淋。<br><strong>Semmi</strong>：列出、说出。<br><strong>żewġ tipi ta’ ħelu</strong>：两种甜食。<br><strong>li hemm fis-silta</strong>：文章里有的。<br><strong>jissemmew</strong>：被提到。<br><strong>il-kantucci u l-ġelat</strong>：两种甜食。</td></tr></tbody></table><hr><h2 id="_2-形容词的性别与比较" tabindex="-1">2 形容词的性别与比较 <a class="header-anchor" href="#_2-形容词的性别与比较" aria-label="Permalink to &quot;2 形容词的性别与比较&quot;">​</a></h2><h3 id="形容词的性别与比较" tabindex="-1">形容词的性别与比较 <a class="header-anchor" href="#形容词的性别与比较" aria-label="Permalink to &quot;形容词的性别与比较&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原句／例子</th><th>中文与解析</th></tr></thead><tbody><tr><td>L-aġġettiv jiddeskrivi n-nom u dan ukoll għandu ġens.</td><td>形容词描述名词；名词也有性别。<br><strong>L-aġġettiv</strong>：形容词。<br><strong>jiddeskrivi</strong>：描述。<br><strong>n-nom</strong>：名词。<br><strong>u dan ukoll</strong>：而这个也。<br><strong>għandu</strong>：有。<br><strong>ġens</strong>：语法性别。</td></tr><tr><td>L-aġġettiv irid jaqbel mal-ġens tan-nom ukoll.</td><td>形容词须与名词的性别一致。<br><strong>irid</strong>：必须。<br><strong>jaqbel</strong>：一致。<br><strong>mal-ġens</strong>：与性别，ma’ + 定冠词。<br><strong>tan-nom</strong>：名词的。<br><strong>ukoll</strong>：也。</td></tr><tr><td>Tifel kbir – tifla kbira</td><td>大男孩——大女孩。<br><strong>tifel / tifla</strong>：男孩／女孩。<br><strong>kbir / kbira</strong>：大的，阳／阴性。</td></tr><tr><td>Raġel xiħ – mara xiħa</td><td>年老男人——年老女人。<br><strong>raġel / mara</strong>：男人／女人。<br><strong>xiħ / xiħa</strong>：年老的，阳／阴性。</td></tr><tr><td>Kowt iswed – beritta sewda</td><td>黑外套——黑帽子。<br><strong>kowt / beritta</strong>：外套／帽子。<br><strong>iswed / sewda</strong>：黑色，阳／阴性；不是一律在末尾加 a。</td></tr><tr><td>Meta tqabbel ħaġa ma’ oħra tuża l-komparattiv.</td><td>将一物与另一物比较时用比较级。<br><strong>Meta</strong>：当……时。<br><strong>tqabbel</strong>：你比较。<br><strong>ħaġa</strong>：事物。<br><strong>ma’ oħra</strong>：与另一个。<br><strong>tuża</strong>：你使用。<br><strong>l-komparattiv</strong>：比较级。</td></tr><tr><td>Meta tqabbel iktar minn żewġ oġġetti flimkien, tuża s-superlattiv.</td><td>教材说：比较两个以上对象时使用最高级。实际关键是表达某范围内“最……”，不是单凭数量机械选词。<br><strong>iktar minn</strong>：多于。<br><strong>żewġ oġġetti</strong>：两个对象。<br><strong>flimkien</strong>：一起。<br><strong>s-superlattiv</strong>：最高级。</td></tr></tbody></table><p>图片：<strong>kbir → ikbar → l-ikbar</strong>＝大 → 更大 → 最大。比较常搭配 <strong>minn</strong>（比），最高级常说明 <strong>fil-klassi / minn kulħadd</strong>（班里／所有人中）。原文 <strong>P.eż.</strong>＝pereżempju，“例如”。</p><h3 id="表格补全" tabindex="-1">表格补全 <a class="header-anchor" href="#表格补全" aria-label="Permalink to &quot;表格补全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阳性</th><th>阴性</th><th>比较级</th><th>最高级</th><th>中文</th></tr></thead><tbody><tr><td>tqil</td><td>tqila</td><td>itqal</td><td>l-itqal</td><td>重／更重／最重</td></tr><tr><td>frisk</td><td>friska</td><td>iktar frisk / friska</td><td>l-iktar frisk / friska</td><td>凉爽／更新鲜，按所修饰名词选性别</td></tr><tr><td>ħafna</td><td>不适用</td><td>iktar</td><td>l-iktar</td><td>多／更多／最多；数量词的特殊行</td></tr><tr><td>kbir</td><td>kbira</td><td>ikbar</td><td>l-ikbar</td><td>大／更大／最大</td></tr><tr><td>sabiħ</td><td>sabiħa</td><td>isbaħ</td><td>l-isbaħ</td><td>美／更美／最美</td></tr><tr><td>qawwi</td><td>qawwija</td><td>aqwa</td><td>l-aqwa</td><td>强／更强／最强，也可“出色”</td></tr><tr><td>tajjeb</td><td>tajba</td><td>itjeb</td><td>l-itjeb</td><td>好／更好／最好</td></tr></tbody></table><p><code>iktar frisk</code> 是本题给出的分析式比较；不要为了套规则擅改原题为别的词。最高级中的 <code>l-</code> 是定冠词的形式。</p><hr><h2 id="_3-形容词词干表-全部补全" tabindex="-1">3 形容词词干表：全部补全 <a class="header-anchor" href="#_3-形容词词干表-全部补全" aria-label="Permalink to &quot;3 形容词词干表：全部补全&quot;">​</a></h2><h3 id="词干变化表-全部补全" tabindex="-1">词干变化表：全部补全 <a class="header-anchor" href="#词干变化表-全部补全" aria-label="Permalink to &quot;词干变化表：全部补全&quot;">​</a></h3><p>每行从左到右为“阳性原级、阴性原级、比较级、最高级”。中文栏同时给出词义，比较级读“更……”，最高级读“最……”。</p><table tabindex="0"><thead><tr><th>阳性</th><th>阴性</th><th>比较级</th><th>最高级</th><th>中文与用法</th></tr></thead><tbody><tr><td>sabiħ</td><td>sabiħa</td><td>isbaħ</td><td>l-isbaħ</td><td>美丽；sabiħa 配阴性名词</td></tr><tr><td>ikrah</td><td>kerha</td><td>ikreh</td><td>l-ikreh</td><td>丑；阴性词干变化明显</td></tr><tr><td>tajjeb</td><td>tajba</td><td>itjeb</td><td>l-itjeb</td><td>好、好吃；与第 1 页食物呼应</td></tr><tr><td>ħażin</td><td>ħażina</td><td>eħżen</td><td>l-eħżen</td><td>坏、糟糕</td></tr><tr><td>għoli</td><td>għolja</td><td>ogħla</td><td>l-ogħla</td><td>高，也可价格高</td></tr><tr><td>irħis</td><td>irħisa</td><td>irħas</td><td>l-irħas</td><td>便宜</td></tr><tr><td>oħxon</td><td>ħoxna</td><td>eħxen</td><td>l-eħxen</td><td>厚、粗、胖；依语境</td></tr><tr><td>irqiq</td><td>rqiqa</td><td>irqaq</td><td>l-irqaq</td><td>薄、细、瘦</td></tr><tr><td>kbir</td><td>kbira</td><td>ikbar</td><td>l-ikbar</td><td>大，亦可年龄较大</td></tr><tr><td>żgħir</td><td>żgħira</td><td>iżgħar</td><td>l-iżgħar</td><td>小、年幼</td></tr><tr><td>ċkejken</td><td>ċkejkna</td><td>iċken</td><td>l-iċken</td><td>小巧、很小</td></tr><tr><td>tqil</td><td>tqila</td><td>itqal</td><td>l-itqal</td><td>重，也可艰难</td></tr><tr><td>ħafif</td><td>ħafifa</td><td>eħfef</td><td>l-eħfef</td><td>轻、容易</td></tr><tr><td>dejjaq</td><td>dejqa</td><td>idjaq</td><td>l-idjaq</td><td>狭窄</td></tr><tr><td>wiesa’</td><td>wiesgħa</td><td>usa’</td><td>l-usa’</td><td>宽敞；保留末尾撇号</td></tr><tr><td>qawwi</td><td>qawwija</td><td>aqwa</td><td>l-aqwa</td><td>强、有力、出色</td></tr><tr><td>għażiż</td><td>għażiża</td><td>egħżeż</td><td>l-egħżeż</td><td>亲爱的、珍贵的</td></tr><tr><td>twil</td><td>twila</td><td>itwal</td><td>l-itwal</td><td>长、高；用于人可指身高</td></tr><tr><td>qasir</td><td>qasira</td><td>iqsar</td><td>l-iqsar</td><td>短、矮</td></tr><tr><td>fqir</td><td>fqira</td><td>ifqar</td><td>l-ifqar</td><td>贫穷</td></tr><tr><td>xiħ</td><td>xiħa</td><td>ixjeħ</td><td>l-ixjeħ</td><td>年老，常用于有生命者</td></tr><tr><td>qadim</td><td>qadima</td><td>eqdem</td><td>l-eqdem</td><td>陈旧、古老，常用于物</td></tr><tr><td>ġdid</td><td>ġdida</td><td>iġded</td><td>l-iġded</td><td>新</td></tr></tbody></table><h3 id="分析式比较" tabindex="-1">分析式比较 <a class="header-anchor" href="#分析式比较" aria-label="Permalink to &quot;分析式比较&quot;">​</a></h3><p><code>Il-komparattiv u s-superlattiv mhux dejjem jinħadmu b’dan il-mod. Xi aġġettivi jeħtieġu ż-żieda tal-kelma…</code></p><p>译：比较级和最高级并不总按这种方式构成；有些形容词需要增加一个词。</p><p><strong>Il-komparattiv u s-superlattiv</strong>：比较级与最高级。<br><strong>mhux dejjem</strong>：不总是。<br><strong>jinħadmu</strong>：被构成／形成。<br><strong>b’dan il-mod</strong>：以这种方式。<br><strong>Xi aġġettivi</strong>：一些形容词。<br><strong>jeħtieġu</strong>：需要。<br><strong>ż-żieda</strong>：增加。<br><strong>tal-kelma</strong>：一个词的。</p><table tabindex="0"><thead><tr><th>阳性</th><th>阴性</th><th>比较级参考填写</th><th>最高级参考填写</th><th>中文</th></tr></thead><tbody><tr><td>bravu</td><td>brava</td><td>iktar bravu / brava</td><td>l-iktar bravu / brava</td><td>能干、擅长</td></tr><tr><td>intelliġenti</td><td>intelliġenti</td><td>iktar intelliġenti</td><td>l-iktar intelliġenti</td><td>聪明，阴阳同形</td></tr><tr><td>stupidu</td><td>stupida</td><td>iktar stupidu / stupida</td><td>l-iktar stupidu / stupida</td><td>愚笨，用来称人可能冒犯</td></tr><tr><td>modern</td><td>moderna</td><td>iktar modern / moderna</td><td>l-iktar modern / moderna</td><td>现代</td></tr><tr><td>sinjur</td><td>sinjura</td><td>iktar sinjur / sinjura</td><td>l-iktar sinjur / sinjura</td><td>富有；此处不是“先生／女士”称谓</td></tr><tr><td>abjad</td><td>bajda</td><td>iktar abjad / bajda</td><td>l-iktar abjad / bajda</td><td>白</td></tr><tr><td>ċar</td><td>ċara</td><td>iktar ċar / ċara</td><td>l-iktar ċar / ċara</td><td>清晰、浅色</td></tr><tr><td>skur</td><td>skura</td><td>iktar skur / skura</td><td>l-iktar skur / skura</td><td>深色、暗</td></tr></tbody></table><p><strong>iktar / iżjed</strong> 均为“更”；<strong>l-iktar / l-iżjed</strong> 均为“最”。这里遵循教材的分析式练习，并不表示这些词在所有语境下都排斥其他比较表达。</p><hr><h2 id="_4-十五道完整填空答案" tabindex="-1">4 十五道完整填空答案 <a class="header-anchor" href="#_4-十五道完整填空答案" aria-label="Permalink to &quot;4 十五道完整填空答案&quot;">​</a></h2><h3 id="_15-道完整填空答案" tabindex="-1">15 道完整填空答案 <a class="header-anchor" href="#_15-道完整填空答案" aria-label="Permalink to &quot;15 道完整填空答案&quot;">​</a></h3><p>题目 <code>Imla l-vojt bil-komparattiv jew bis-superlattiv, skont l-aġġettiv li hemm fil-parentesi</code>：按括号中的形容词，用比较级或最高级填空。<strong>Imla</strong>：填；<strong>il-vojt</strong>：空白；<strong>bil-</strong>：用；<strong>jew</strong>：或；<strong>skont</strong>：根据；<strong>fil-parentesi</strong>：括号内。</p><table tabindex="0"><thead><tr><th>补全句子</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Id-dar tiegħi hija <strong>ikbar</strong> minn tiegħek, imma ta’ ommi hija <strong>l-ikbar</strong> minn tagħna kollha.</td><td>我的房子比你的大，不过母亲的房子是我们所有房子中最大的。<br><strong>Id-dar tiegħi</strong>：我的房子。<br><strong>hija ikbar</strong>：更大。<br><strong>minn tiegħek</strong>：比你的。<br><strong>imma</strong>：但是。<br><strong>ta’ ommi</strong>：我母亲的，省略 dar。<br><strong>hija l-ikbar</strong>：是最大的。<br><strong>minn tagħna kollha</strong>：在我们所有人的之中。</td></tr><tr><td>2. Daż-żarbun huwa <strong>l-eqdem</strong> wieħed.</td><td>这双鞋是最旧的那一双。<br><strong>Daż-żarbun</strong>：这鞋／这双鞋，da- 与定冠词组合，不是“日子”。<br><strong>huwa</strong>：是。<br><strong>l-eqdem</strong>：最旧。<br><strong>wieħed</strong>：一个，指这一件／这一双。</td></tr><tr><td>3. Il-Ġappun huwa <strong>l-isbaħ</strong> pajjiż li qatt mort.</td><td>日本是我去过的最美国家。<br><strong>Il-Ġappun</strong>：日本。<br><strong>huwa l-isbaħ pajjiż</strong>：是最美的国家。<br><strong>li qatt mort</strong>：我曾去过的；较完整可加 fih。</td></tr><tr><td>4. Bl-ajruplan tasal <strong>iktar malajr</strong> milli bil-vapur.</td><td>坐飞机比坐船更快到达。<br><strong>Bl-ajruplan</strong>：乘飞机。<br><strong>tasal</strong>：你到达。<br><strong>iktar malajr</strong>：更快，也可 iżjed malajr。<br><strong>milli</strong>：比起。<br><strong>bil-vapur</strong>：乘船。</td></tr><tr><td>5. Mill-istudenti tal-klassi, jien <strong>l-iżgħar</strong> waħda.</td><td>我是班里学生中年龄最小的女生。<br><strong>Mill-istudenti</strong>：在学生之中。<br><strong>tal-klassi</strong>：班级的。<br><strong>jien</strong>：我。<br><strong>l-iżgħar</strong>：最小。<br><strong>waħda</strong>：阴性“一个”，提示说话者为女性。</td></tr><tr><td>6. Dan il-kowt huwa <strong>eħxen</strong> mill-ieħor.</td><td>这件外套比另一件厚。<br><strong>Dan il-kowt</strong>：这件外套。<br><strong>huwa eħxen</strong>：更厚。<br><strong>mill-ieħor</strong>：比另一个。</td></tr><tr><td>7. Slovenja hija pajjiż <strong>iktar frisk</strong> minn Malta.</td><td>斯洛文尼亚是个比马耳他凉爽的国家。<br><strong>Slovenja</strong>：斯洛文尼亚。<br><strong>hija pajjiż</strong>：是一个国家。<br><strong>iktar frisk</strong>：更凉爽，配阳性 pajjiż。<br><strong>minn Malta</strong>：比马耳他。</td></tr><tr><td>8. L-Underground hija <strong>iktar effiċjenti</strong> mit-trasport pubbliku ta’ fuq l-art.</td><td>地铁比地面公共交通更高效。<br><strong>L-Underground</strong>：地下铁路／地铁。<br><strong>hija</strong>：是。<br><strong>iktar effiċjenti</strong>：更高效。<br><strong>mit-trasport pubbliku</strong>：比公共交通。<br><strong>ta’ fuq l-art</strong>：地面上的。</td></tr><tr><td>9. Dan l-ikel huwa <strong>itjeb</strong> minn tal-bieraħ.</td><td>这顿食物比昨天的好吃。<br><strong>Dan l-ikel</strong>：这些食物。<br><strong>huwa itjeb</strong>：更好。<br><strong>minn tal-bieraħ</strong>：比昨天的，省略 ikel。</td></tr><tr><td>10. Xagħar iz-zija huwa <strong>iqsar</strong> minn tiegħi.</td><td>姑姨的头发比我的短。<br><strong>Xagħar</strong>：头发。<br><strong>iz-zija</strong>：姑妈／姨妈。<br><strong>huwa iqsar</strong>：更短。<br><strong>minn tiegħi</strong>：比我的。</td></tr><tr><td>11. It-triq tagħna hija <strong>l-idjaq</strong> fir-raħal kollu.</td><td>我们这条街是全村最窄的。<br><strong>It-triq tagħna</strong>：我们的街。<br><strong>hija l-idjaq</strong>：最狭窄。<br><strong>fir-raħal kollu</strong>：在整个村子里。</td></tr><tr><td>12. <strong>L-ixjeħ</strong> persuna fid-dinja għandha mija u għoxrin sena!</td><td>世界最年长者 120 岁！仅按原题练语法，不作现时事实依据。<br><strong>L-ixjeħ persuna</strong>：最年老的人。<br><strong>fid-dinja</strong>：世界上。<br><strong>għandha</strong>：她／这个人有，年龄用“有”。<br><strong>mija u għoxrin sena</strong>：120 年／岁。</td></tr><tr><td>13. Ġorr dan il-basket għax <strong>eħfef</strong> mill-ieħor.</td><td>拿这个包，因为它比另一个轻。<br><strong>Ġorr</strong>：拿／搬，命令式。<br><strong>dan il-basket</strong>：这个包。<br><strong>għax</strong>：因为。<br><strong>eħfef</strong>：更轻。<br><strong>mill-ieħor</strong>：比另一个。</td></tr><tr><td>14. Dan l-eżami kien <strong>itqal</strong> minn ta’ qablu.</td><td>这次考试比前一次更难。<br><strong>Dan l-eżami</strong>：这次考试。<br><strong>kien</strong>：当时是。<br><strong>itqal</strong>：更重，引申为更难。<br><strong>minn ta’ qablu</strong>：比它之前的那次。</td></tr><tr><td>15. Il-vjaġġ lejn l-Ingilterra huwa <strong>itwal</strong> minn dak ta’ lejn l-Italja.</td><td>去英格兰的旅程比去意大利的长。<br><strong>Il-vjaġġ</strong>：旅程。<br><strong>lejn l-Ingilterra</strong>：去英格兰。<br><strong>huwa itwal</strong>：更长。<br><strong>minn dak</strong>：比那个。<br><strong>ta’ lejn l-Italja</strong>：去意大利的旅程。</td></tr></tbody></table><hr><h2 id="_5-过去时-十七个完整例句" tabindex="-1">5 过去时：十七个完整例句 <a class="header-anchor" href="#_5-过去时-十七个完整例句" aria-label="Permalink to &quot;5 过去时：十七个完整例句&quot;">​</a></h2><h3 id="过去时-17-个完整例句" tabindex="-1">过去时：17 个完整例句 <a class="header-anchor" href="#过去时-17-个完整例句" aria-label="Permalink to &quot;过去时：17 个完整例句&quot;">​</a></h3><p><code>Il-Verbi fil-Passat</code>：过去时动词。<strong>Semitiċi</strong>：闪米特来源类；<strong>li ġejjin mill-Għarbi</strong>：来自阿拉伯语的。题目 <strong>Ikteb sentenza b’dawn il-verbi</strong>＝用这些动词各写一句话；<strong>Ikteb</strong> 写，<strong>sentenza</strong> 句子，<strong>b’dawn</strong> 用这些。</p><p>这里的词头是第三人称阳性单数过去时“他……了”，不是不定式或命令式。以下例句保持该形式。</p><table tabindex="0"><thead><tr><th>动词与例句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. <strong>Kiteb</strong> — Ilbieraħ Mark kiteb ittra twila lil ħabibu biex jirrakkontalu dwar il-vaganza tiegħu.</td><td>昨天 Mark 给朋友写了封长信，讲述自己的假期。<br><strong>Ilbieraħ</strong>：昨天。<br><strong>Mark</strong>：人名。<br><strong>kiteb</strong>：他写了。<br><strong>ittra twila</strong>：一封长信，阴性。<br><strong>lil ħabibu</strong>：给他的朋友，-u＝他的。<br><strong>biex</strong>：为了。<br><strong>jirrakkontalu</strong>：向他讲述。<br><strong>dwar</strong>：关于。<br><strong>il-vaganza tiegħu</strong>：他的假期。</td></tr><tr><td>2. <strong>Ħareġ</strong> — Wara x-xogħol, Paul ħareġ ma’ sħabu u marru jieklu f’restorant qrib il-baħar.</td><td>下班后 Paul 和朋友出去，在海边餐厅吃饭。<br><strong>Wara x-xogħol</strong>：下班后。<br><strong>Paul ħareġ</strong>：Paul 出去了。<br><strong>ma’ sħabu</strong>：和他的朋友们。<br><strong>u marru</strong>：他们去了。<br><strong>jieklu</strong>：吃饭。<br><strong>f’restorant</strong>：在餐馆。<br><strong>qrib il-baħar</strong>：靠近海边。</td></tr><tr><td>3. <strong>Fetaħ</strong> — Filgħodu missieri fetaħ it-twieqi tal-kċina għax il-kamra kienet sħuna ħafna.</td><td>早晨父亲开了厨房窗户，因为房间很热。<br><strong>Filgħodu</strong>：早晨。<br><strong>missieri</strong>：我父亲。<br><strong>fetaħ</strong>：打开了。<br><strong>it-twieqi</strong>：窗户，复数。<br><strong>tal-kċina</strong>：厨房的。<br><strong>għax</strong>：因为。<br><strong>il-kamra</strong>：房间。<br><strong>kienet sħuna ħafna</strong>：当时很热。</td></tr><tr><td>4. <strong>Raqad</strong> — It-tifel raqad kmieni għax l-għada kellu jmur l-iskola u jagħmel eżami importanti.</td><td>男孩很早睡了，因为第二天要上学参加重要考试。<br><strong>It-tifel</strong>：男孩。<br><strong>raqad kmieni</strong>：早早睡了。<br><strong>għax</strong>：因为。<br><strong>l-għada</strong>：第二天。<br><strong>kellu</strong>：他当时须／有。<br><strong>jmur l-iskola</strong>：去学校。<br><strong>u jagħmel</strong>：并参加／做。<br><strong>eżami importanti</strong>：重要考试。</td></tr><tr><td>5. <strong>Rikeb</strong> — It-turist rikeb il-ferrovija minn Ruma għal Firenze u gawda l-veduta mit-tieqa.</td><td>游客坐火车从罗马到佛罗伦萨，从窗边欣赏风景。<br><strong>It-turist</strong>：游客。<br><strong>rikeb</strong>：乘坐了。<br><strong>il-ferrovija</strong>：火车。<br><strong>minn Ruma għal Firenze</strong>：从罗马到佛罗伦萨。<br><strong>u gawda</strong>：并欣赏。<br><strong>l-veduta</strong>：景色。<br><strong>mit-tieqa</strong>：从窗户。</td></tr><tr><td>6. <strong>Ħasel</strong> — Wara l-ikla, ħija ħasel il-platti u naddaf il-mejda biex jgħin lil ommi.</td><td>饭后哥哥洗碗擦桌，帮助母亲。<br><strong>Wara l-ikla</strong>：饭后。<br><strong>ħija</strong>：我的兄弟。<br><strong>ħasel</strong>：洗了。<br><strong>il-platti</strong>：盘子。<br><strong>u naddaf</strong>：并清洁了。<br><strong>il-mejda</strong>：桌子。<br><strong>biex jgħin</strong>：为了帮助。<br><strong>lil ommi</strong>：我母亲。</td></tr><tr><td>7. <strong>Għalaq</strong> — Is-sid għalaq il-ħanut fis-sebgħa ta’ filgħaxija u mar lura d-dar bil-karozza.</td><td>店主晚上七点关店，开车回家。<br><strong>Is-sid</strong>：主人／店主。<br><strong>għalaq</strong>：关闭。<br><strong>il-ħanut</strong>：商店。<br><strong>fis-sebgħa</strong>：七点。<br><strong>ta’ filgħaxija</strong>：晚上的。<br><strong>u mar lura d-dar</strong>：并回家了。<br><strong>bil-karozza</strong>：乘汽车。</td></tr><tr><td>8. <strong>Għamel</strong> — Nhar is-Sibt, David għamel kejk taċ-ċikkulata għal għeluq snin oħtu u żejnu bil-frott.</td><td>星期六 David 为姐姐生日做巧克力蛋糕，并用水果装饰。<br><strong>Nhar is-Sibt</strong>：在星期六。<br><strong>David għamel</strong>：David 做了。<br><strong>kejk taċ-ċikkulata</strong>：巧克力蛋糕。<br><strong>għal għeluq snin</strong>：为了生日。<br><strong>oħtu</strong>：他的姐妹。<br><strong>u żejnu</strong>：并装饰了它，-u 指蛋糕。<br><strong>bil-frott</strong>：用水果。</td></tr><tr><td>9. <strong>Tela’</strong> — Il-viżitatur tela’ fuq it-torri biex jieħu ritratti tal-belt u tal-port minn fuq.</td><td>访客登上塔楼，从高处拍城市和港口。<br><strong>Il-viżitatur</strong>：访客。<br><strong>tela’</strong>：上去了，保留撇号。<br><strong>fuq it-torri</strong>：到塔上。<br><strong>biex jieħu ritratti</strong>：为了拍照。<br><strong>tal-belt u tal-port</strong>：城市和港口的。<br><strong>minn fuq</strong>：从上方。</td></tr><tr><td>10. <strong>Mela</strong> — Qabel il-vjaġġ, Mario mela l-flixkun bl-ilma u poġġieh fil-basket ħdejn l-ikel.</td><td>出发前 Mario 灌满水瓶，放在包里食物旁。<br><strong>Qabel il-vjaġġ</strong>：旅行前。<br><strong>Mario mela</strong>：Mario 装满了。<br><strong>l-flixkun</strong>：瓶子。<br><strong>bl-ilma</strong>：用水。<br><strong>u poġġieh</strong>：并把它放下。<br><strong>fil-basket</strong>：在包里。<br><strong>ħdejn l-ikel</strong>：食物旁。<br><strong>mela</strong>：这里是动词，不是口头语“那么”。</td></tr><tr><td>11. <strong>Wera</strong> — L-għalliem wera lill-istudenti mappa ta’ Malta u spjega fejn jinsabu l-bliet ewlenin.</td><td>老师给学生看马耳他地图，并说明主要城市的位置。<br><strong>L-għalliem</strong>：男老师。<br><strong>wera</strong>：展示。<br><strong>lill-istudenti</strong>：给学生们。<br><strong>mappa ta’ Malta</strong>：马耳他地图。<br><strong>u spjega</strong>：并解释。<br><strong>fejn jinsabu</strong>：位于哪里。<br><strong>l-bliet ewlenin</strong>：主要城市。</td></tr><tr><td>12. <strong>Saq</strong> — Missieri saq bil-mod lejn l-ajruport għax kienet ix-xita u kien hemm ħafna traffiku.</td><td>父亲慢慢开车去机场，因为下雨而且车多。<br><strong>Missieri</strong>：我父亲。<br><strong>saq</strong>：驾驶了。<br><strong>bil-mod</strong>：缓慢地。<br><strong>lejn l-ajruport</strong>：朝机场。<br><strong>għax</strong>：因为。<br><strong>kienet ix-xita</strong>：当时下雨。<br><strong>u kien hemm</strong>：而且有。<br><strong>ħafna traffiku</strong>：很多交通／车辆。</td></tr><tr><td>13. <strong>Dar</strong> — Il-gwida dar mal-belt mal-grupp u wriehom il-knejjes, il-pjazez u l-bini antik.</td><td>导游带团游览城市，给他们看教堂、广场和古建筑。<br><strong>Il-gwida</strong>：导游，此例为男性。<br><strong>dar</strong>：转了一圈／游览了；不是名词“房子”。<br><strong>mal-belt</strong>：沿着城里。<br><strong>mal-grupp</strong>：和团队。<br><strong>u wriehom</strong>：并向他们展示。<br><strong>il-knejjes</strong>：教堂们。<br><strong>il-pjazez</strong>：广场们。<br><strong>u l-bini antik</strong>：与古老建筑。</td></tr><tr><td>14. <strong>Mar</strong> — Il-Ħadd, Peter mar għand in-nanna u ħa miegħu ftit frott u kejk magħmul id-dar.</td><td>星期天 Peter 去奶奶家，带了水果和家制蛋糕。<br><strong>Il-Ħadd</strong>：星期天。<br><strong>Peter mar</strong>：Peter 去了。<br><strong>għand in-nanna</strong>：去奶奶／外婆那里。<br><strong>u ħa miegħu</strong>：并随身带去。<br><strong>ftit frott</strong>：一些水果。<br><strong>u kejk</strong>：和蛋糕。<br><strong>magħmul id-dar</strong>：家里做的。</td></tr><tr><td>15. <strong>Għam</strong> — Fis-sajf li għadda, Tom għam fil-baħar għal nofs siegħa qabel ma kiel ma’ sħabu.</td><td>去年夏天 Tom 在海里游了半小时，之后与朋友吃饭。<br><strong>Fis-sajf li għadda</strong>：上个夏天。<br><strong>Tom għam</strong>：Tom 游泳了。<br><strong>fil-baħar</strong>：在海里。<br><strong>għal nofs siegħa</strong>：持续半小时。<br><strong>qabel ma</strong>：在……之前。<br><strong>kiel</strong>：他吃了。<br><strong>ma’ sħabu</strong>：与朋友们。</td></tr><tr><td>16. <strong>Qam</strong> — Albert qam fis-sitta ta’ filgħodu biex jilħaq il-karozza tal-linja u jasal fil-ħin għax-xogħol.</td><td>Albert 早上六点起床，赶公交准时上班。<br><strong>Albert qam</strong>：Albert 起床了。<br><strong>fis-sitta ta’ filgħodu</strong>：早上六点。<br><strong>biex jilħaq</strong>：为了赶上。<br><strong>il-karozza tal-linja</strong>：公共汽车。<br><strong>u jasal</strong>：并到达。<br><strong>fil-ħin</strong>：准时。<br><strong>għax-xogħol</strong>：去工作。</td></tr><tr><td>17. <strong>Kiel</strong> — Wara mixja twila, Daniel kiel platt għaġin bil-ħaxix u xorob tazza ilma fir-restorant.</td><td>长途散步后 Daniel 在餐馆吃蔬菜意面，喝了一杯水。<br><strong>Wara mixja twila</strong>：长距离步行后。<br><strong>Daniel kiel</strong>：Daniel 吃了。<br><strong>platt għaġin</strong>：一盘意面。<br><strong>bil-ħaxix</strong>：配蔬菜。<br><strong>u xorob</strong>：并喝了。<br><strong>tazza ilma</strong>：一杯水。<br><strong>fir-restorant</strong>：在餐馆里。</td></tr></tbody></table><hr><h2 id="_6-另外十八个过去时例句" tabindex="-1">6 另外十八个过去时例句 <a class="header-anchor" href="#_6-另外十八个过去时例句" aria-label="Permalink to &quot;6 另外十八个过去时例句&quot;">​</a></h2><h3 id="另-18-个过去时例句" tabindex="-1">另 18 个过去时例句 <a class="header-anchor" href="#另-18-个过去时例句" aria-label="Permalink to &quot;另 18 个过去时例句&quot;">​</a></h3><p><code>Mhux Semitiċi – li ġejjin mir-Rumanz u mill-Ingliż</code>：非闪米特来源类——来自罗曼语与英语。<strong>mhux</strong>：不是；<strong>li ġejjin</strong>：来源于；<strong>mir-Rumanz</strong>：来自罗曼语；<strong>mill-Ingliż</strong>：来自英语。这是教材分组，不据此对每个词作严格词源结论。</p><table tabindex="0"><thead><tr><th>动词与例句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. <strong>Aċċetta</strong> — John aċċetta l-istedina ta’ ħabibu u mar għall-festa flimkien ma’ martu s-Sibt filgħaxija.</td><td>John 接受朋友邀请，周六晚上与妻子赴宴。<br><strong>John aċċetta</strong>：John 接受了。<br><strong>l-istedina</strong>：邀请。<br><strong>ta’ ħabibu</strong>：他朋友的。<br><strong>u mar għall-festa</strong>：并去了聚会。<br><strong>flimkien ma’ martu</strong>：和妻子一起。<br><strong>s-Sibt filgħaxija</strong>：星期六晚上。</td></tr><tr><td>2. <strong>Eduka</strong> — L-għalliem eduka lit-tfal dwar l-ambjent u għallimhom kif inaqqsu l-iskart fl-iskola.</td><td>老师教育儿童认识环境，并教他们减少校内垃圾。<br><strong>L-għalliem</strong>：老师。<br><strong>eduka</strong>：教育了。<br><strong>lit-tfal</strong>：儿童们。<br><strong>dwar l-ambjent</strong>：关于环境。<br><strong>u għallimhom</strong>：并教他们。<br><strong>kif inaqqsu</strong>：如何减少。<br><strong>l-iskart</strong>：垃圾。<br><strong>fl-iskola</strong>：在学校。</td></tr><tr><td>3. <strong>Falla</strong> — L-istudent falla l-eżami tal-Malti, iżda ddeċieda li jistudja aktar u jerġa’ jipprova.</td><td>学生马耳他语考试没过，但决定多学习再尝试。<br><strong>L-istudent</strong>：学生。<br><strong>falla</strong>：未通过。<br><strong>l-eżami tal-Malti</strong>：马耳他语考试。<br><strong>iżda</strong>：但是。<br><strong>ddeċieda</strong>：决定了。<br><strong>li jistudja aktar</strong>：要更多学习。<br><strong>u jerġa’ jipprova</strong>：并再次尝试。</td></tr><tr><td>4. <strong>Ibbukkja</strong> — Qabel is-safra, Mark ibbukkja kamra f’lukanda qrib l-istazzjon biex ikun jista’ jivvjaġġa faċilment.</td><td>旅行前 Mark 订了车站附近酒店，方便出行。<br><strong>Qabel is-safra</strong>：旅行前。<br><strong>Mark ibbukkja</strong>：Mark 预订了。<br><strong>kamra f’lukanda</strong>：酒店房间。<br><strong>qrib l-istazzjon</strong>：车站附近。<br><strong>biex ikun jista’</strong>：为了能够。<br><strong>jivvjaġġa faċilment</strong>：轻松出行。</td></tr><tr><td>5. <strong>Iċċarġja</strong> — Mario iċċarġja l-mowbajl tiegħu qabel ħareġ mid-dar għax kellu bżonn juża l-mappa.</td><td>Mario 出门前给手机充电，因为要使用地图。<br><strong>Mario iċċarġja</strong>：Mario 充电了。<br><strong>l-mowbajl tiegħu</strong>：他的手机。<br><strong>qabel ħareġ</strong>：出去之前。<br><strong>mid-dar</strong>：从家里。<br><strong>għax kellu bżonn</strong>：因为需要。<br><strong>juża l-mappa</strong>：使用地图。</td></tr><tr><td>6. <strong>Iddefinixxa</strong> — Il-professur iddefinixxa l-kelma l-ġdida u ta żewġ eżempji biex l-istudenti jifhmuha aħjar.</td><td>教授解释新词定义，举两例帮助学生理解。<br><strong>Il-professur</strong>：教授。<br><strong>iddefinixxa</strong>：定义了。<br><strong>l-kelma l-ġdida</strong>：这个新词。<br><strong>u ta</strong>：并给了。<br><strong>żewġ eżempji</strong>：两个例子。<br><strong>biex l-istudenti</strong>：为了让学生们。<br><strong>jifhmuha aħjar</strong>：更好理解它，-ha 指 kelma。</td></tr><tr><td>7. <strong>Iffajlja</strong> — L-impjegat iffajlja d-dokumenti tal-klijenti fl-uffiċċju u kiteb id-data fuq kull fajl.</td><td>员工在办公室归档客户文件，在每份档案写上日期。<br><strong>L-impjegat</strong>：员工。<br><strong>iffajlja</strong>：归档了。<br><strong>d-dokumenti tal-klijenti</strong>：客户文件。<br><strong>fl-uffiċċju</strong>：在办公室。<br><strong>u kiteb</strong>：并写。<br><strong>id-data</strong>：日期。<br><strong>fuq kull fajl</strong>：每份档案上。</td></tr><tr><td>8. <strong>Iffavurixxa</strong> — Iffavurixxa lil student wieħed waqt il-logħba, u għalhekk l-oħrajn ħassewhom imdejqin.</td><td>他在游戏中偏袒一名学生，因此其他人感到不快。<br><strong>Iffavurixxa</strong>：他偏袒／优待了，主语由动词表示。<br><strong>lil student wieħed</strong>：一名学生。<br><strong>waqt il-logħba</strong>：游戏期间。<br><strong>u għalhekk</strong>：并因此。<br><strong>l-oħrajn</strong>：其他人。<br><strong>ħassewhom imdejqin</strong>：感到难过／不快。</td></tr><tr><td>9. <strong>Iffilmja</strong> — It-turist iffilmja l-festa tar-raħal u bagħat il-filmat lill-familja tiegħu meta wasal id-dar.</td><td>游客拍下村庆，回家后把视频发给家人。<br><strong>It-turist</strong>：游客。<br><strong>iffilmja</strong>：拍摄了。<br><strong>l-festa tar-raħal</strong>：村庄节庆。<br><strong>u bagħat il-filmat</strong>：并发送视频。<br><strong>lill-familja tiegħu</strong>：给他的家人。<br><strong>meta wasal id-dar</strong>：到家时。</td></tr><tr><td>10. <strong>Ipparkja</strong> — Paul ipparkja l-karozza f’parkeġġ kbir u mexa sal-mużew biex jiltaqa’ ma’ sħabu.</td><td>Paul 把车停在大停车场，步行到博物馆见朋友。<br><strong>Paul ipparkja</strong>：Paul 停车了。<br><strong>l-karozza</strong>：汽车。<br><strong>f’parkeġġ kbir</strong>：大停车场里。<br><strong>u mexa</strong>：并走路。<br><strong>sal-mużew</strong>：到博物馆。<br><strong>biex jiltaqa’</strong>：为了会见。<br><strong>ma’ sħabu</strong>：与朋友们。</td></tr><tr><td>11. <strong>Ippubblika</strong> — Il-kittieb ippubblika ktieb ġdid dwar l-istorja ta’ Malta u ppreżentah lill-qarrejja fil-librerija.</td><td>作者出版了马耳他历史新书，在图书馆向读者介绍。<br><strong>Il-kittieb</strong>：作家。<br><strong>ippubblika</strong>：出版了。<br><strong>ktieb ġdid</strong>：一本新书。<br><strong>dwar l-istorja ta’ Malta</strong>：关于马耳他历史。<br><strong>u ppreżentah</strong>：并介绍它。<br><strong>lill-qarrejja</strong>：给读者们。<br><strong>fil-librerija</strong>：在图书馆。</td></tr><tr><td>12. <strong>Irreklama</strong> — Is-sid irreklama r-restorant il-ġdid fuq l-internet u offra ikla speċjali lill-ewwel klijenti.</td><td>店主在网上宣传新餐厅，为首批顾客提供特别餐。<br><strong>Is-sid</strong>：店主。<br><strong>irreklama</strong>：做广告了。<br><strong>r-restorant il-ġdid</strong>：新餐馆。<br><strong>fuq l-internet</strong>：网上。<br><strong>u offra</strong>：并提供。<br><strong>ikla speċjali</strong>：特别餐。<br><strong>lill-ewwel klijenti</strong>：给首批顾客。</td></tr><tr><td>13. <strong>Iwweldja</strong> — Il-ħaddiem iwweldja żewġ biċċiet tal-metall biex isewwi l-grada l-qadima tad-dar tagħna.</td><td>工人焊接两块金属，修我们家的旧大门。<br><strong>Il-ħaddiem</strong>：工人。<br><strong>iwweldja</strong>：焊接了。<br><strong>żewġ biċċiet tal-metall</strong>：两块金属。<br><strong>biex isewwi</strong>：为了修理。<br><strong>l-grada l-qadima</strong>：旧大门。<br><strong>tad-dar tagħna</strong>：我们家的。</td></tr><tr><td>14. <strong>Kompla</strong> — Wara waqfa qasira, Joseph kompla jaħdem fuq il-proġett sakemm lesta kollox qabel filgħaxija.</td><td>短暂休息后 Joseph 继续做项目，晚前完成。<br><strong>Wara waqfa qasira</strong>：短暂停顿后。<br><strong>Joseph kompla</strong>：Joseph 继续了。<br><strong>jaħdem fuq il-proġett</strong>：做这个项目。<br><strong>sakemm</strong>：直到。<br><strong>lesta kollox</strong>：完成一切。<br><strong>qabel filgħaxija</strong>：晚间之前。</td></tr><tr><td>15. <strong>Pinġa</strong> — It-tifel pinġa stampa tal-baħar bil-lapsijiet tal-kulur u taha lil ommu bħala rigal.</td><td>男孩用彩铅画了海景，送给母亲。<br><strong>It-tifel pinġa</strong>：男孩画了。<br><strong>stampa tal-baħar</strong>：海的图画。<br><strong>bil-lapsijiet tal-kulur</strong>：用彩色铅笔。<br><strong>u taha</strong>：并给了它。<br><strong>lil ommu</strong>：给他母亲。<br><strong>bħala rigal</strong>：作为礼物。</td></tr><tr><td>16. <strong>Printja</strong> — L-istudent printja l-biljetti tal-ajru u poġġiehom mal-passaport biex ma jinsihomx qabel is-safra.</td><td>学生打印机票，和护照放一起，以免旅行前忘记。<br><strong>L-istudent printja</strong>：学生打印了。<br><strong>l-biljetti tal-ajru</strong>：机票。<br><strong>u poġġiehom</strong>：并把它们放下。<br><strong>mal-passaport</strong>：与护照一起。<br><strong>biex ma jinsihomx</strong>：为了不忘记它们。<br><strong>qabel is-safra</strong>：旅行之前。</td></tr><tr><td>17. <strong>Skurja</strong> — Il-plejer skurja żewġ gowls fit-tieni taqsima u għen lit-tim tiegħu jirbaħ il-logħba.</td><td>球员下半场进两球，帮助球队赢球。<br><strong>Il-plejer skurja</strong>：球员得分了。<br><strong>żewġ gowls</strong>：两个进球。<br><strong>fit-tieni taqsima</strong>：第二节／下半场。<br><strong>u għen</strong>：并帮助。<br><strong>lit-tim tiegħu</strong>：他的球队。<br><strong>jirbaħ il-logħba</strong>：赢得比赛。</td></tr><tr><td>18. <strong>Studja</strong> — Andrew studja l-Malti għal siegħa kuljum u pprattika t-taħdit ma’ ħabib Malti wara x-xogħol.</td><td>Andrew 每天学一小时马耳他语，下班后和马耳他朋友练口语。<br><strong>Andrew studja</strong>：Andrew 学习了。<br><strong>l-Malti</strong>：马耳他语。<br><strong>għal siegħa kuljum</strong>：每天一小时。<br><strong>u pprattika</strong>：并练习。<br><strong>t-taħdit</strong>：口语。<br><strong>ma’ ħabib Malti</strong>：与一位马耳他朋友。<br><strong>wara x-xogħol</strong>：下班后。</td></tr></tbody></table><hr><h2 id="_7-题目与-56-个变位形式" tabindex="-1">7 题目与 56 个变位形式 <a class="header-anchor" href="#_7-题目与-56-个变位形式" aria-label="Permalink to &quot;7 题目与 56 个变位形式&quot;">​</a></h2><h3 id="题目与-56-个变位" tabindex="-1">题目与 56 个变位 <a class="header-anchor" href="#题目与-56-个变位" aria-label="Permalink to &quot;题目与 56 个变位&quot;">​</a></h3><p><code>Issa agħżel erba’ verbi Semitiċi u erbgħa oħra li mhumiex, u kkonjugahom fil-persuni kollha fil-passat</code>：现在选四个闪米特类动词和另外四个非此类动词，用过去时变出所有人称。</p><p><strong>Issa</strong>：现在。<br><strong>agħżel</strong>：选择。<br><strong>erba’ verbi</strong>：四个动词。<br><strong>u erbgħa oħra</strong>：另外四个，此处数词独立使用。<br><strong>li mhumiex</strong>：不是这一类的。<br><strong>ikkonjugahom</strong>：把它们变位，-hom＝它们。<br><strong>fil-persuni kollha</strong>：所有人称。<br><strong>fil-passat</strong>：过去时。</p><table tabindex="0"><thead><tr><th>人称</th><th>kiteb 写</th><th>fetaħ 打开</th><th>ħasel 洗</th><th>għamel 做</th></tr></thead><tbody><tr><td>Jien 我</td><td>ktibt</td><td>ftaħt</td><td>ħsilt</td><td>għamilt</td></tr><tr><td>Int 你</td><td>ktibt</td><td>ftaħt</td><td>ħsilt</td><td>għamilt</td></tr><tr><td>Huwa 他</td><td>kiteb</td><td>fetaħ</td><td>ħasel</td><td>għamel</td></tr><tr><td>Hija 她</td><td>kitbet</td><td>fetħet</td><td>ħaslet</td><td>għamlet</td></tr><tr><td>Aħna 我们</td><td>ktibna</td><td>ftaħna</td><td>ħsilna</td><td>għamilna</td></tr><tr><td>Intom 你们</td><td>ktibtu</td><td>ftaħtu</td><td>ħsiltu</td><td>għamiltu</td></tr><tr><td>Huma 他们／她们</td><td>kitbu</td><td>fetħu</td><td>ħaslu</td><td>għamlu</td></tr></tbody></table><table tabindex="0"><thead><tr><th>人称</th><th>aċċetta 接受</th><th>ibbukkja 预订</th><th>ipparkja 停车</th><th>studja 学习</th></tr></thead><tbody><tr><td>Jien 我</td><td>aċċettajt</td><td>ibbukkjajt</td><td>ipparkjajt</td><td>studjajt</td></tr><tr><td>Int 你</td><td>aċċettajt</td><td>ibbukkjajt</td><td>ipparkjajt</td><td>studjajt</td></tr><tr><td>Huwa 他</td><td>aċċetta</td><td>ibbukkja</td><td>ipparkja</td><td>studja</td></tr><tr><td>Hija 她</td><td>aċċettat</td><td>ibbukkjat</td><td>ipparkjat</td><td>studjat</td></tr><tr><td>Aħna 我们</td><td>aċċettajna</td><td>ibbukkjajna</td><td>ipparkjajna</td><td>studjajna</td></tr><tr><td>Intom 你们</td><td>aċċettajtu</td><td>ibbukkjajtu</td><td>ipparkjajtu</td><td>studjajtu</td></tr><tr><td>Huma 他们／她们</td><td>aċċettaw</td><td>ibbukkjaw</td><td>ipparkjaw</td><td>studjaw</td></tr></tbody></table><p>第一、第二人称单数常同形，需靠主语和语境区别；例如 <strong>ktibt</strong>＝我写了／你写了。<strong>-na</strong> 常标“我们”，<strong>-tu</strong> 常标“你们”，但不可只往所有原形后机械加词尾；注意 <strong>kiteb → ktibna</strong>、<strong>għamel → għamilna</strong>。第三人称复数常有 <strong>-u / -w</strong>。两表共八个动词、每个七个人称。</p><hr><h2 id="_8-口语主题" tabindex="-1">8 口语主题 <a class="header-anchor" href="#_8-口语主题" aria-label="Permalink to &quot;8 口语主题&quot;">​</a></h2><h3 id="主题一-上次旅行-逐题回答" tabindex="-1">主题一：上次旅行，逐题回答 <a class="header-anchor" href="#主题一-上次旅行-逐题回答" aria-label="Permalink to &quot;主题一：上次旅行，逐题回答&quot;">​</a></h3><p><code>It-Taħdit</code>＝口语。<code>Iddeskrivi l-aħħar darba li sifirt</code>＝描述最近一次出国旅行。<strong>Iddeskrivi</strong>：描述；<strong>l-aħħar darba</strong>：最后／最近一次；<strong>li sifirt</strong>：你旅行了的那次。以下以虚构的意大利之行为例。</p><table tabindex="0"><thead><tr><th>提示与较完整回答</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>Meta mort? — Mort l-Italja f’April li għadda u qattajt hemm ġimgħa waqt il-vaganzi.</td><td>何时去？——上个四月去意大利，假期在那里待了一周。<br><strong>Meta mort</strong>：你何时去了。<br><strong>Mort l-Italja</strong>：我去了意大利。<br><strong>f’April li għadda</strong>：上个四月。<br><strong>u qattajt</strong>：并度过。<br><strong>hemm ġimgħa</strong>：在那里一周。<br><strong>waqt il-vaganzi</strong>：假期期间。</td></tr><tr><td>Fejn mort? — Żort Ruma u Firenze, fejn rajt mużewijiet, knejjes antiki u pjazez sbieħ.</td><td>去哪？——罗马和佛罗伦萨，看了博物馆、古教堂和美丽广场。<br><strong>Fejn mort</strong>：你去了哪里。<br><strong>Żort</strong>：我参观了。<br><strong>Ruma u Firenze</strong>：罗马和佛罗伦萨。<br><strong>fejn rajt</strong>：在那里我看见。<br><strong>mużewijiet</strong>：博物馆。<br><strong>knejjes antiki</strong>：古老教堂。<br><strong>u pjazez sbieħ</strong>：和漂亮广场。</td></tr><tr><td>Ma’ min mort? — Mort ma’ żewġ ħbieb tal-kors u qsamna kamra f’lukanda żgħira.</td><td>跟谁？——两位同学，合住小酒店的一间房。<br><strong>Ma’ min</strong>：和谁。<br><strong>Mort ma’</strong>：我和……去。<br><strong>żewġ ħbieb tal-kors</strong>：两位课程朋友。<br><strong>u qsamna</strong>：并分享／合用。<br><strong>kamra</strong>：房间。<br><strong>f’lukanda żgħira</strong>：在小酒店。</td></tr><tr><td>Liema mezz tat-trasport użajt? — Ħadt l-ajruplan minn Malta u użajt il-ferrovija biex nivvjaġġa bejn il-bliet.</td><td>用什么交通？——从马耳他坐飞机，城际坐火车。<br><strong>Liema mezz tat-trasport</strong>：哪种交通工具。<br><strong>użajt</strong>：你用了／我用了。<br><strong>Ħadt l-ajruplan</strong>：我搭飞机。<br><strong>minn Malta</strong>：从马耳他。<br><strong>u użajt il-ferrovija</strong>：并用火车。<br><strong>biex nivvjaġġa</strong>：为了出行。<br><strong>bejn il-bliet</strong>：城市之间。</td></tr><tr><td>Iddeskrivi l-postijiet li żort. — Ruma kienet kbira u storika, waqt li Firenze kienet sabiħa u mimlija arti.</td><td>描述去过的地方。——罗马宏大且富历史，佛罗伦萨美丽、艺术丰富。<br><strong>l-postijiet li żort</strong>：你游览的地方。<br><strong>Ruma kienet</strong>：罗马当时是。<br><strong>kbira u storika</strong>：大而有历史。<br><strong>waqt li</strong>：而、与此同时。<br><strong>Firenze kienet sabiħa</strong>：佛罗伦萨很美。<br><strong>u mimlija arti</strong>：并充满艺术。</td></tr><tr><td>Liema l-iktar ħaġa li għoġbitek? — L-iktar li għoġobni kien il-katidral ta’ Firenze għax il-bini tiegħu huwa impressjonanti.</td><td>最喜欢什么？——佛罗伦萨大教堂，建筑很壮观。<br><strong>Liema l-iktar ħaġa</strong>：最……的是哪样。<br><strong>li għoġbitek</strong>：你喜欢的。<br><strong>L-iktar li għoġobni</strong>：我最喜欢的。<br><strong>kien il-katidral ta’ Firenze</strong>：是佛罗伦萨大教堂。<br><strong>għax</strong>：因为。<br><strong>il-bini tiegħu</strong>：它的建筑。<br><strong>huwa impressjonanti</strong>：很壮观。</td></tr><tr><td>Kien hemm xi ħaġa li dejqitek? — Iva, il-kjuwijiet twal dejquni, speċjalment meta kellna nistennew barra fix-xemx.</td><td>有不喜欢的吗？——长队令人烦，尤其在外面晒太阳等候。<br><strong>Kien hemm</strong>：当时有吗。<br><strong>xi ħaġa li dejqitek</strong>：令你不快的事。<br><strong>Iva</strong>：是。<br><strong>il-kjuwijiet twal</strong>：长队。<br><strong>dejquni</strong>：使我不快，-ni＝我。<br><strong>speċjalment meta</strong>：特别当。<br><strong>kellna nistennew</strong>：我们不得不等。<br><strong>barra fix-xemx</strong>：在外面太阳下。</td></tr><tr><td>Inqalgħet xi problema? — Darba tlifna l-ferrovija, iżda sibna oħra u wasalna fil-lukanda qabel filgħaxija.</td><td>出过问题吗？——错过一次火车，但找到另一班，晚上前到酒店。<br><strong>Inqalgħet</strong>：发生了。<br><strong>xi problema</strong>：某个问题。<br><strong>Darba</strong>：有一次。<br><strong>tlifna l-ferrovija</strong>：我们错过火车。<br><strong>iżda sibna oħra</strong>：但找到另一班。<br><strong>u wasalna fil-lukanda</strong>：并到酒店。<br><strong>qabel filgħaxija</strong>：晚间之前。</td></tr></tbody></table><h3 id="主题二-最喜欢的地方" tabindex="-1">主题二：最喜欢的地方 <a class="header-anchor" href="#主题二-最喜欢的地方" aria-label="Permalink to &quot;主题二：最喜欢的地方&quot;">​</a></h3><p><code>Iddeskrivi l-post favorit tiegħek</code>＝描述你最喜欢的地方；<strong>il-post</strong> 地方，<strong>favorit tiegħek</strong> 你最爱的。以下选择马耳他的 Mellieħa 海滩。</p><table tabindex="0"><thead><tr><th>提示与回答</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>Fejn jinsab dan il-post? F’liema pajjiż? — Il-post favorit tiegħi huwa l-bajja tal-Mellieħa, fit-tramuntana ta’ Malta.</td><td>位于哪里、哪个国家？——马耳他北部 Mellieħa 海湾。<br><strong>Fejn jinsab</strong>：位于哪里。<br><strong>dan il-post</strong>：这个地方。<br><strong>F’liema pajjiż</strong>：在哪个国家。<br><strong>Il-post favorit tiegħi</strong>：我最爱的地方。<br><strong>huwa l-bajja tal-Mellieħa</strong>：是 Mellieħa 海湾。<br><strong>fit-tramuntana ta’ Malta</strong>：马耳他北部。</td></tr><tr><td>Ġewwa jew barra? — Huwa post fil-beraħ, fejn nista’ nimxi fuq ir-ramel u ngħum fil-baħar.</td><td>室内还是室外？——户外，可沙滩散步、海里游泳。<br><strong>Ġewwa jew barra</strong>：里面或外面。<br><strong>Huwa post fil-beraħ</strong>：它是户外地点。<br><strong>fejn nista’</strong>：在那里我能。<br><strong>nimxi fuq ir-ramel</strong>：走在沙上。<br><strong>u ngħum fil-baħar</strong>：并在海里游泳。</td></tr><tr><td>Tmur spiss hemmhekk? — Fis-sajf immur hemm darba fil-ġimgħa, ġeneralment il-Ħadd filgħodu ma’ sħabi.</td><td>常去吗？——夏季每周一次，通常周日早与朋友去。<br><strong>Tmur spiss</strong>：你常去吗。<br><strong>hemmhekk</strong>：那里。<br><strong>Fis-sajf</strong>：夏季。<br><strong>immur hemm</strong>：我去那里。<br><strong>darba fil-ġimgħa</strong>：每周一次。<br><strong>ġeneralment</strong>：通常。<br><strong>il-Ħadd filgħodu</strong>：星期天早上。<br><strong>ma’ sħabi</strong>：和我的朋友。</td></tr><tr><td>Għaliex jogħġbok? — Jogħġobni għax nista’ nistrieħ, nieħu arja friska u nqatta’ ħin mal-ħbieb.</td><td>为什么喜欢？——可以休息、呼吸新鲜空气、陪朋友。<br><strong>Għaliex</strong>：为什么。<br><strong>jogħġbok / jogħġobni</strong>：使你／我喜欢，回指 post。<br><strong>għax nista’</strong>：因为我能。<br><strong>nistrieħ</strong>：休息。<br><strong>nieħu arja friska</strong>：呼吸新鲜空气。<br><strong>u nqatta’ ħin</strong>：并度过时间。<br><strong>mal-ħbieb</strong>：与朋友。</td></tr><tr><td>X’aġġettivi tista’ tuża biex tiddeskrivi dan il-post? — Nista’ ngħid li huwa sabiħ, spazjuż u kwiet kmieni filgħodu.</td><td>用哪些形容词？——美丽、宽敞，清早安静。<br><strong>X’aġġettivi</strong>：什么形容词。<br><strong>tista’ tuża</strong>：你能使用。<br><strong>biex tiddeskrivi</strong>：为了描述。<br><strong>dan il-post</strong>：这个地方。<br><strong>Nista’ ngħid li</strong>：我可以说。<br><strong>huwa sabiħ, spazjuż u kwiet</strong>：它美丽、宽敞、安静，均配 post。<br><strong>kmieni filgħodu</strong>：清晨。</td></tr><tr><td>X’tista’ tara u tisma’ meta tkun hemm? — Nara l-baħar blu u d-dgħajjes, u nisma’ l-mewġ u t-tfal jilagħbu.</td><td>看见、听见什么？——蓝海、小船、海浪和儿童玩耍声。<br><strong>X’tista’ tara u tisma’</strong>：你能看到和听到什么。<br><strong>meta tkun hemm</strong>：当你在那里。<br><strong>Nara</strong>：我看见。<br><strong>l-baħar blu u d-dgħajjes</strong>：蓝海和船。<br><strong>u nisma’</strong>：并听见。<br><strong>l-mewġ</strong>：海浪。<br><strong>u t-tfal jilagħbu</strong>：孩子们玩耍。</td></tr><tr><td>Xi tħoss meta tkun hemm? — Meta nkun hemm inħossni kalm u ferħan, u ninsa ftit l-istress tax-xogħol.</td><td>感受如何？——平静、开心，暂忘工作压力。<br><strong>Xi tħoss</strong>：你感觉什么。<br><strong>meta tkun hemm</strong>：当你在那里。<br><strong>Meta nkun hemm</strong>：当我在那里。<br><strong>inħossni</strong>：我感到，-ni 反身。<br><strong>kalm u ferħan</strong>：平静、开心，男性说话者；女性 kalma u ferħana。<br><strong>u ninsa ftit</strong>：并暂时忘记。<br><strong>l-istress tax-xogħol</strong>：工作压力。</td></tr></tbody></table><hr><h2 id="_9-写作-一次旅行" tabindex="-1">9 写作：一次旅行 <a class="header-anchor" href="#_9-写作-一次旅行" aria-label="Permalink to &quot;9 写作：一次旅行&quot;">​</a></h2><h3 id="写作-一次旅行" tabindex="-1">写作：一次旅行 <a class="header-anchor" href="#写作-一次旅行" aria-label="Permalink to &quot;写作：一次旅行&quot;">​</a></h3><p><code>Il-Kitba – Agħżel waħda minn pg. 7 u ikteb ftit sentenzi dwarha</code>：写作——选一个主题，写几句话。<strong>Agħżel</strong>：选；<strong>waħda</strong>：一个；<strong>minn</strong>：从……中；<strong>ikteb</strong>：写；<strong>ftit sentenzi</strong>：几句话；<strong>dwarha</strong>：关于它。<code>pg. 7</code> 为旧引用，本册对应第 8 页。</p><h3 id="连贯范文" tabindex="-1">连贯范文 <a class="header-anchor" href="#连贯范文" aria-label="Permalink to &quot;连贯范文&quot;">​</a></h3><p>F’April li għadda mort l-Italja ma’ żewġ ħbieb tal-kors. Ħadna l-ajruplan minn Malta u mbagħad il-ferrovija bejn Ruma u Firenze. Qgħadna f’lukanda żgħira qrib iċ-ċentru u mxejna ħafna kuljum. F’Ruma żorna mużew u rajna ħafna bini antik, waqt li f’Firenze għoġobna ħafna l-katidral. L-ikel kien mill-aqwa, speċjalment l-għaġin, u wara l-pranzu dejjem kilna ġelat. Darba tlifna l-ferrovija, iżda stennejna oħra u ma kellniex problemi kbar. L-iktar ħaġa li għoġbitni kienet li qattajt ħin sabiħ ma’ sħabi. Nixtieq nerġa’ mmur hemm u nżur postijiet oħra li ma rajtx din id-darba.</p><table tabindex="0"><thead><tr><th>范文句子</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>F’April li għadda mort l-Italja ma’ żewġ ħbieb tal-kors.</td><td>上个四月我和两位同学去意大利。<br><strong>F’April li għadda</strong>：上个四月。<br><strong>mort</strong>：我去了。<br><strong>l-Italja</strong>：意大利。<br><strong>ma’ żewġ ħbieb</strong>：和两位朋友。<br><strong>tal-kors</strong>：这个课程的。</td></tr><tr><td>Ħadna l-ajruplan minn Malta u mbagħad il-ferrovija bejn Ruma u Firenze.</td><td>我们从马耳他搭飞机，之后坐火车往返罗马、佛罗伦萨。<br><strong>Ħadna</strong>：我们搭乘。<br><strong>l-ajruplan</strong>：飞机。<br><strong>minn Malta</strong>：从马耳他。<br><strong>u mbagħad</strong>：然后。<br><strong>il-ferrovija</strong>：火车。<br><strong>bejn Ruma u Firenze</strong>：罗马和佛罗伦萨之间。</td></tr><tr><td>Qgħadna f’lukanda żgħira qrib iċ-ċentru u mxejna ħafna kuljum.</td><td>住在市中心附近的小酒店，每天走很多路。<br><strong>Qgħadna</strong>：我们住了。<br><strong>f’lukanda żgħira</strong>：小酒店里。<br><strong>qrib iċ-ċentru</strong>：中心附近。<br><strong>u mxejna</strong>：并走路了。<br><strong>ħafna kuljum</strong>：每天很多。</td></tr><tr><td>F’Ruma żorna mużew u rajna ħafna bini antik, waqt li f’Firenze għoġobna ħafna l-katidral.</td><td>罗马看博物馆和古建筑，佛罗伦萨最喜欢大教堂。<br><strong>F’Ruma</strong>：在罗马。<br><strong>żorna mużew</strong>：我们参观博物馆。<br><strong>u rajna ħafna bini antik</strong>：并看见很多古建筑。<br><strong>waqt li</strong>：而。<br><strong>f’Firenze</strong>：在佛罗伦萨。<br><strong>għoġobna ħafna</strong>：我们很喜欢，-na＝我们。<br><strong>l-katidral</strong>：大教堂。</td></tr><tr><td>L-ikel kien mill-aqwa, speċjalment l-għaġin, u wara l-pranzu dejjem kilna ġelat.</td><td>食物很棒，尤其意面；午饭后我们总吃冰淇淋。<br><strong>L-ikel</strong>：食物。<br><strong>kien mill-aqwa</strong>：非常出色。<br><strong>speċjalment l-għaġin</strong>：尤其意面。<br><strong>u wara l-pranzu</strong>：并在午饭后。<br><strong>dejjem</strong>：总是。<br><strong>kilna ġelat</strong>：我们吃冰淇淋。</td></tr><tr><td>Darba tlifna l-ferrovija, iżda stennejna oħra u ma kellniex problemi kbar.</td><td>有次错过火车，但等了下一班，没有大问题。<br><strong>Darba</strong>：有一次。<br><strong>tlifna l-ferrovija</strong>：错过火车。<br><strong>iżda stennejna oħra</strong>：但我们等另一班。<br><strong>u ma kellniex</strong>：而且我们没有。<br><strong>problemi kbar</strong>：大问题。</td></tr><tr><td>L-iktar ħaġa li għoġbitni kienet li qattajt ħin sabiħ ma’ sħabi.</td><td>最喜欢的是与朋友度过愉快时光。<br><strong>L-iktar ħaġa</strong>：最……的事。<br><strong>li għoġbitni</strong>：我喜欢的。<br><strong>kienet li</strong>：是……这件事。<br><strong>qattajt ħin sabiħ</strong>：我度过美好时光。<br><strong>ma’ sħabi</strong>：与朋友。</td></tr><tr><td>Nixtieq nerġa’ mmur hemm u nżur postijiet oħra li ma rajtx din id-darba.</td><td>想再去，看看这次没看过的地方。<br><strong>Nixtieq</strong>：我想。<br><strong>nerġa’ mmur</strong>：再次去。<br><strong>hemm</strong>：那里。<br><strong>u nżur postijiet oħra</strong>：并参观别处。<br><strong>li ma rajtx</strong>：我没看过的。<br><strong>din id-darba</strong>：这一次。</td></tr></tbody></table><hr><h2 id="_10-非正式信件-十个空" tabindex="-1">10 非正式信件：十个空 <a class="header-anchor" href="#_10-非正式信件-十个空" aria-label="Permalink to &quot;10 非正式信件：十个空&quot;">​</a></h2><h3 id="非正式信件-十空答案" tabindex="-1">非正式信件：十空答案 <a class="header-anchor" href="#非正式信件-十空答案" aria-label="Permalink to &quot;非正式信件：十空答案&quot;">​</a></h3><p>顺序：<strong>tajba → ħadna → morna → żorna → tlajt → l-ogħla → mill-aqwa → kilna → xtaqt → prova</strong>。每个词用一次。</p><p>原指令大意：用下方动词、形容词补完非正式信，设想写给一位女朋友，告诉她最近一次旅行做了什么、发生了什么。</p><p><strong>Ittra Informali</strong>：非正式信。<br><strong>Imla l-vojt</strong>：填空。<br><strong>bil-verbi u l-aġġettivi</strong>：用动词和形容词。<br><strong>li hemm taħt</strong>：列在下方的。<br><strong>Immaġina</strong>：设想。<br><strong>li se tibgħat</strong>：你将寄。<br><strong>lil ħabibtek</strong>：给你的女性朋友。<br><strong>sabiex tgħidilha</strong>：为了告诉她。<br><strong>x’għamilt u x’ġara</strong>：你做了什么、发生了什么。<br><strong>waqt vaganza</strong>：假期中。<br><strong>li mort ftit ilu</strong>：你不久前去的。</p><h3 id="补全信件" tabindex="-1">补全信件 <a class="header-anchor" href="#补全信件" aria-label="Permalink to &quot;补全信件&quot;">​</a></h3><p>22, Viv,<br> Triq it-Tagħlim,<br> Il-Fgura<br> FGR2144</p><p>Għażiża Laura,</p><p>Kif int? Jien ninsab tajba u nixtieq nirrakkuntalek daqsxejn x’għamilna Spanja! Kemm ħadna gost u kemm hemm x’tara!</p><p>L-ewwel post li morna kien Barċellona, imbagħad għamilna l-aħħar jumejn tal-vaganza ġewwa Girona u Tossa del Mar. Żorna l-Akkwarju ta’ Barċellona, is-Sagrada Famiglia, Parc Guell u Portaventura! Hemm tlajt fuq l-ogħla rollercoaster li qatt irkibt! Kemm werżaqna mill-qalb! L-ikel huwa mill-aqwa wkoll, kilna ħafna paella u tapas tradizzjonali Spanjoli.</p><p>Veru xtaqt li kont magħna Laura u tgħidx kemm semmejniek! Issa prova ejja magħna l-vaganza li jmiss, ħa mmorru Ċipru nduru l-bajjiet sbieħ t’hemm.</p><p>Ċaw!</p><p>Tania</p><h3 id="逐句解析" tabindex="-1">逐句解析 <a class="header-anchor" href="#逐句解析" aria-label="Permalink to &quot;逐句解析&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原句</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>Għażiża Laura, / Kif int?</td><td>亲爱的 Laura：你好吗？<br><strong>Għażiża</strong>：亲爱的，女性收信人。<br><strong>Laura</strong>：人名。<br><strong>Kif</strong>：怎样。<br><strong>int</strong>：你。</td></tr><tr><td>Jien ninsab tajba u nixtieq nirrakkuntalek daqsxejn x’għamilna Spanja!</td><td>我很好，想给你讲讲我们在西班牙做了什么。<br><strong>Jien</strong>：我。<br><strong>ninsab tajba</strong>：状态很好，女性说话者。<br><strong>u nixtieq</strong>：并且想。<br><strong>nirrakkuntalek</strong>：给你讲述，-lek＝给你。<br><strong>daqsxejn</strong>：一点儿。<br><strong>x’għamilna</strong>：我们做了什么。<br><strong>Spanja</strong>：在西班牙。</td></tr><tr><td>Kemm ħadna gost u kemm hemm x’tara!</td><td>我们玩得多开心，那里真有很多可看！<br><strong>Kemm</strong>：多么，感叹。<br><strong>ħadna gost</strong>：我们很开心。<br><strong>u kemm hemm</strong>：而且有那么多。<br><strong>x’tara</strong>：你可看的东西。</td></tr><tr><td>L-ewwel post li morna kien Barċellona, imbagħad għamilna l-aħħar jumejn tal-vaganza ġewwa Girona u Tossa del Mar.</td><td>第一站巴塞罗那，最后两天在 Girona 和 Tossa del Mar。<br><strong>L-ewwel post</strong>：第一处地点。<br><strong>li morna</strong>：我们去的，较完整 li morna fih。<br><strong>kien Barċellona</strong>：是巴塞罗那。<br><strong>imbagħad</strong>：然后。<br><strong>għamilna</strong>：我们度过，此处不是制造。<br><strong>l-aħħar jumejn</strong>：最后两天，jumejn 双数。<br><strong>tal-vaganza</strong>：假期的。<br><strong>ġewwa</strong>：在。<br><strong>Girona u Tossa del Mar</strong>：两处地名。</td></tr><tr><td>Żorna l-Akkwarju ta’ Barċellona, is-Sagrada Famiglia, Parc Guell u Portaventura!</td><td>参观了巴塞罗那水族馆、圣家堂、古埃尔公园和冒险港乐园。<br><strong>Żorna</strong>：我们参观。<br><strong>l-Akkwarju</strong>：水族馆。<br><strong>ta’ Barċellona</strong>：巴塞罗那的。<br><strong>is-Sagrada Famiglia / Parc Guell / Portaventura</strong>：原教材景点拼写。<br><strong>u</strong>：和。</td></tr><tr><td>Hemm tlajt fuq l-ogħla rollercoaster li qatt irkibt!</td><td>我在那里坐上了自己坐过最高的过山车！<br><strong>Hemm</strong>：那里。<br><strong>tlajt fuq</strong>：我登上／搭上。<br><strong>l-ogħla</strong>：最高。<br><strong>rollercoaster</strong>：过山车，借用英语。<br><strong>li qatt irkibt</strong>：我曾坐过的。</td></tr><tr><td>Kemm werżaqna mill-qalb!</td><td>我们真是放声尖叫！<br><strong>Kemm</strong>：多么。<br><strong>werżaqna</strong>：我们尖叫了。<br><strong>mill-qalb</strong>：发自内心、尽情地。</td></tr><tr><td>L-ikel huwa mill-aqwa wkoll, kilna ħafna paella u tapas tradizzjonali Spanjoli.</td><td>食物也很棒，吃了很多西班牙传统海鲜饭和小食。<br><strong>L-ikel</strong>：食物。<br><strong>huwa mill-aqwa</strong>：很出色。<br><strong>wkoll</strong>：也，ukoll 的形式。<br><strong>kilna ħafna</strong>：我们吃了很多。<br><strong>paella u tapas</strong>：西班牙饭与小食。<br><strong>tradizzjonali Spanjoli</strong>：传统西班牙式的。</td></tr><tr><td>Veru xtaqt li kont magħna Laura u tgħidx kemm semmejniek!</td><td>Laura，我真希望你当时也和我们在一起，我们不知提了你多少次！<br><strong>Veru</strong>：真的。<br><strong>xtaqt</strong>：我希望／想过。<br><strong>li kont magħna</strong>：你当时与我们同在，表示愿望，不说她真去了。<br><strong>u tgħidx kemm</strong>：别提有多……，感叹惯用语。<br><strong>semmejniek</strong>：我们提到你了，-k＝你。</td></tr><tr><td>Issa prova ejja magħna l-vaganza li jmiss, ħa mmorru Ċipru nduru l-bajjiet sbieħ t’hemm.</td><td>下次尽量和我们一起，去塞浦路斯游览那里的美丽海滩。<br><strong>Issa</strong>：现在／那么。<br><strong>prova</strong>：试着、尽量，命令式。<br><strong>ejja magħna</strong>：跟我们来。<br><strong>l-vaganza li jmiss</strong>：下一次假期。<br><strong>ħa mmorru</strong>：让我们去／我们打算去。<br><strong>Ċipru</strong>：塞浦路斯。<br><strong>nduru</strong>：我们游览。<br><strong>l-bajjiet sbieħ</strong>：美丽海滩。<br><strong>t’hemm</strong>：那里的。</td></tr><tr><td>Ċaw! / Tania</td><td>再见！Tania。<br><strong>Ċaw</strong>：非正式你好／再见。<br><strong>Tania</strong>：写信人署名。</td></tr></tbody></table><p>地址中的 <strong>Triq it-Tagħlim</strong>＝“学习街”，<strong>Il-Fgura</strong> 为地名，<strong>FGR2144</strong> 是教材邮编；<strong>Viv</strong> 为房名，不强译。</p><hr><h2 id="_11-给表姐妹的完整参考信" tabindex="-1">11 给表姐妹的完整参考信 <a class="header-anchor" href="#_11-给表姐妹的完整参考信" aria-label="Permalink to &quot;11 给表姐妹的完整参考信&quot;">​</a></h2><h3 id="给表姐妹的完整参考信" tabindex="-1">给表姐妹的完整参考信 <a class="header-anchor" href="#给表姐妹的完整参考信" aria-label="Permalink to &quot;给表姐妹的完整参考信&quot;">​</a></h3><p>题意：给女性堂／表亲写非正式信，描述上一次假期见过的地方，参考旅行提示。</p><p><strong>Ikteb ittra informali</strong>：写非正式信。<br><strong>lill-kuġina</strong>：给女性堂／表亲。<br><strong>sabiex tiddeskrivi</strong>：为了描述。<br><strong>l-postijiet li rajt</strong>：你见过的地方。<br><strong>waqt il-vaganza li għaddiet</strong>：上一次假期期间。<br><strong>Uża l-punti</strong>：使用要点。<br><strong>minn paġna 7</strong>：原页码引用，内容对应本稿第 8 页。<br><strong>biex jgħinuk</strong>：让它们帮助你。</p><p>37, Ward u Żahar<br> Triq il-Fjuri<br> Ħad-Dingli<br> DNG 1682</p><p>L-1 ta’ Awwissu, 2023</p><p>Għażiża Maria,</p><p>Kif int? Nispera li inti u l-familja tinsabu tajbin. Għadni kif ġejt lura minn vaganza sabiħa fl-Italja u nixtieq ngħidlek x’rajt hemmhekk.</p><p>Mort ma’ żewġ ħbieb tiegħi u qattajna ġimgħa bejn Ruma u Firenze. Sifirna bl-ajruplan minn Malta u wara użajna l-ferrovija. F’Ruma żorna mużewijiet u mxejna fit-toroq antiki qrib iċ-ċentru. L-iktar li għoġobni kien il-katidral ta’ Firenze għax huwa kbir u mimli dettalji sbieħ. Ħadna ħafna ritratti u kull filgħaxija kilna f’restorant differenti. L-għaġin kien mill-aqwa, u dejjem ħallejna ftit spazju għall-ġelat.</p><p>Darba bdiet ix-xita waqt il-mixja, iżda sibna kafetterija u stennejna hemm. Ma ħallejniex it-temp iħassar il-ġurnata, u wara komplejna nduru bil-ferħ. Nixtieq nerġa’ mmur l-Italja fil-futur, u nittama li d-darba li jmiss tiġi magħna.</p><p>Iktibli meta jkollok ftit ħin u għidli kif qattajt il-vaganza tiegħek.</p><p>Insellimlek,</p><p>Anna</p><h3 id="逐句解析-1" tabindex="-1">逐句解析 <a class="header-anchor" href="#逐句解析-1" aria-label="Permalink to &quot;逐句解析&quot;">​</a></h3><table tabindex="0"><thead><tr><th>范文句子</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>Għażiża Maria, Kif int? Nispera li inti u l-familja tinsabu tajbin.</td><td>亲爱的 Maria，你好吗？希望你和家人都好。<br><strong>Għażiża</strong>：亲爱的，阴性。<br><strong>Kif int</strong>：你好吗。<br><strong>Nispera li</strong>：我希望。<br><strong>inti u l-familja</strong>：你与家人。<br><strong>tinsabu tajbin</strong>：你们状态很好，复数。</td></tr><tr><td>Għadni kif ġejt lura minn vaganza sabiħa fl-Italja u nixtieq ngħidlek x’rajt hemmhekk.</td><td>我刚从意大利的美好假期回来，想告诉你所见。<br><strong>Għadni kif</strong>：我刚刚。<br><strong>ġejt lura</strong>：回来。<br><strong>minn vaganza sabiħa</strong>：从美好的假期。<br><strong>fl-Italja</strong>：在意大利。<br><strong>u nixtieq</strong>：并想。<br><strong>ngħidlek</strong>：告诉你。<br><strong>x’rajt</strong>：我看见什么。<br><strong>hemmhekk</strong>：那里。</td></tr><tr><td>Mort ma’ żewġ ħbieb tiegħi u qattajna ġimgħa bejn Ruma u Firenze.</td><td>和两位朋友一起，在罗马、佛罗伦萨待了一周。<br><strong>Mort</strong>：我去了。<br><strong>ma’ żewġ ħbieb tiegħi</strong>：与我的两位朋友。<br><strong>u qattajna</strong>：并度过。<br><strong>ġimgħa</strong>：一周。<br><strong>bejn Ruma u Firenze</strong>：在两城之间。</td></tr><tr><td>Sifirna bl-ajruplan minn Malta u wara użajna l-ferrovija.</td><td>从马耳他搭飞机，之后坐火车。<br><strong>Sifirna</strong>：我们旅行了。<br><strong>bl-ajruplan</strong>：乘飞机。<br><strong>minn Malta</strong>：从马耳他。<br><strong>u wara</strong>：然后。<br><strong>użajna l-ferrovija</strong>：我们使用火车。</td></tr><tr><td>F’Ruma żorna mużewijiet u mxejna fit-toroq antiki qrib iċ-ċentru.</td><td>在罗马参观博物馆，沿中心附近古街散步。<br><strong>F’Ruma</strong>：在罗马。<br><strong>żorna mużewijiet</strong>：我们参观博物馆。<br><strong>u mxejna</strong>：并步行。<br><strong>fit-toroq antiki</strong>：在古老街道上。<br><strong>qrib iċ-ċentru</strong>：中心附近。</td></tr><tr><td>L-iktar li għoġobni kien il-katidral ta’ Firenze għax huwa kbir u mimli dettalji sbieħ.</td><td>最喜欢佛罗伦萨大教堂，宏伟且细节优美。<br><strong>L-iktar li għoġobni</strong>：我最喜欢的。<br><strong>kien il-katidral ta’ Firenze</strong>：是佛罗伦萨大教堂。<br><strong>għax huwa kbir</strong>：因为它很大。<br><strong>u mimli</strong>：并充满。<br><strong>dettalji sbieħ</strong>：美丽细节。</td></tr><tr><td>Ħadna ħafna ritratti u kull filgħaxija kilna f’restorant differenti.</td><td>拍很多照片，每晚在不同餐厅吃饭。<br><strong>Ħadna ħafna ritratti</strong>：拍了很多照片。<br><strong>u kull filgħaxija</strong>：并且每晚。<br><strong>kilna</strong>：我们吃。<br><strong>f’restorant differenti</strong>：在不同餐馆。</td></tr><tr><td>L-għaġin kien mill-aqwa, u dejjem ħallejna ftit spazju għall-ġelat.</td><td>意面很棒，总还留点肚子给冰淇淋。<br><strong>L-għaġin</strong>：意面。<br><strong>kien mill-aqwa</strong>：非常好。<br><strong>u dejjem ħallejna</strong>：而且总留下。<br><strong>ftit spazju</strong>：一些空间。<br><strong>għall-ġelat</strong>：给冰淇淋。</td></tr><tr><td>Darba bdiet ix-xita waqt il-mixja, iżda sibna kafetterija u stennejna hemm.</td><td>有次散步下雨，找到咖啡馆等待。<br><strong>Darba</strong>：有一次。<br><strong>bdiet ix-xita</strong>：开始下雨。<br><strong>waqt il-mixja</strong>：散步期间。<br><strong>iżda sibna kafetterija</strong>：但找到咖啡馆。<br><strong>u stennejna hemm</strong>：并在那里等待。</td></tr><tr><td>Ma ħallejniex it-temp iħassar il-ġurnata, u wara komplejna nduru bil-ferħ.</td><td>没让天气毁掉一天，之后继续开心游览。<br><strong>Ma ħallejniex</strong>：我们没有让。<br><strong>it-temp</strong>：天气。<br><strong>iħassar il-ġurnata</strong>：破坏这一天。<br><strong>u wara</strong>：而后。<br><strong>komplejna nduru</strong>：继续游览。<br><strong>bil-ferħ</strong>：开心地。</td></tr><tr><td>Nixtieq nerġa’ mmur l-Italja fil-futur, u nittama li d-darba li jmiss tiġi magħna.</td><td>想以后再去意大利，希望下次你也同行。<br><strong>Nixtieq nerġa’ mmur</strong>：我想再去。<br><strong>l-Italja fil-futur</strong>：未来去意大利。<br><strong>u nittama li</strong>：并希望。<br><strong>d-darba li jmiss</strong>：下一次。<br><strong>tiġi magħna</strong>：你与我们一起来。</td></tr><tr><td>Iktibli meta jkollok ftit ħin u għidli kif qattajt il-vaganza tiegħek.</td><td>有空写信，告诉我你的假期怎么过。<br><strong>Iktibli</strong>：写给我。<br><strong>meta jkollok ftit ħin</strong>：当你有些时间。<br><strong>u għidli</strong>：并告诉我。<br><strong>kif qattajt</strong>：你怎样度过。<br><strong>il-vaganza tiegħek</strong>：你的假期。</td></tr><tr><td>Insellimlek, Anna</td><td>向你问好，Anna。<br><strong>Insellimlek</strong>：我向你致意，非正式结尾。<br><strong>Anna</strong>：虚构署名。</td></tr></tbody></table><p>地址保留题设：<strong>Ward u Żahar</strong> 房名，可理解为花朵与花香／花簇意象；<strong>Triq il-Fjuri</strong>＝花街；<strong>Ħad-Dingli</strong>＝Dingli 地名；<strong>DNG 1682</strong>＝邮编。<strong>L-1 ta’ Awwissu, 2023</strong>＝2023 年 8 月 1 日，是题目日期，不改成今天。</p><hr><h2 id="_12-交通工具配对" tabindex="-1">12 交通工具配对 <a class="header-anchor" href="#_12-交通工具配对" aria-label="Permalink to &quot;12 交通工具配对&quot;">​</a></h2><h3 id="交通工具配对" tabindex="-1">交通工具配对 <a class="header-anchor" href="#交通工具配对" aria-label="Permalink to &quot;交通工具配对&quot;">​</a></h3><p>题目 <code>Qabbel il-mezz ta’ trasport li jintuża f’din is-sitwazzjoni</code>：配对这种情境使用的交通工具。<strong>Qabbel</strong>：配对／匹配；<strong>il-mezz ta’ trasport</strong>：交通方式；<strong>li jintuża</strong>：被使用的；<strong>f’din is-sitwazzjoni</strong>：在这个情境中。</p><table tabindex="0"><thead><tr><th>选项</th><th>中文</th></tr></thead><tbody><tr><td>rota</td><td>自行车</td></tr><tr><td>ferrovija</td><td>火车</td></tr><tr><td>taxi</td><td>出租车</td></tr><tr><td>vapur</td><td>船、轮船</td></tr><tr><td>tal-linja</td><td>公共汽车，完整可说 karozza tal-linja</td></tr><tr><td>ajruplan</td><td>飞机</td></tr><tr><td>karozza</td><td>汽车</td></tr><tr><td>vann</td><td>厢式车、客货小面包车</td></tr><tr><td>mutur</td><td>摩托车</td></tr></tbody></table><table tabindex="0"><thead><tr><th>原句与配对</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>1. Biex mort mid-dar għall-baħar soqt lilha. Kemm ħriġtha mill-garaxx. — <strong>karozza</strong></td><td>从家去海边，我开它，只需从车库开出来。<br><strong>Biex mort</strong>：为了去／当我去。<br><strong>mid-dar</strong>：从家。<br><strong>għall-baħar</strong>：到海边。<br><strong>soqt</strong>：我开了。<br><strong>lilha</strong>：它，阴性，指 karozza。<br><strong>Kemm</strong>：这里“只需、不过是”。<br><strong>ħriġtha</strong>：我把它开／拿出来，-ha＝它。<br><strong>mill-garaxx</strong>：从车库。</td></tr><tr><td>2. Biex sifirt għal Ċipru rkibt lilu. Domna kważi sagħtejn. — <strong>ajruplan</strong></td><td>去塞浦路斯旅行时坐它，花近两小时。<br><strong>Biex sifirt</strong>：为了旅行。<br><strong>għal Ċipru</strong>：去塞浦路斯。<br><strong>rkibt</strong>：我乘坐了。<br><strong>lilu</strong>：它，阳性，指 ajruplan。<br><strong>Domna</strong>：我们花了。<br><strong>kważi</strong>：差不多。<br><strong>sagħtejn</strong>：两小时，双数。</td></tr><tr><td>3. Biex mort minn Vjenna għall-Islovakkja rkibt lilha. — <strong>ferrovija</strong></td><td>从维也纳去斯洛伐克乘火车。<br><strong>Biex mort</strong>：为了去。<br><strong>minn Vjenna</strong>：从维也纳。<br><strong>għall-Islovakkja</strong>：到斯洛伐克。<br><strong>rkibt lilha</strong>：我乘了它，阴性。<br><strong>ferrovija</strong>：根据选项选火车，不宣称唯一实际路线。</td></tr><tr><td>4. Biex ġarrejt l-affarijiet minn dar għal oħra użajt lilu. — <strong>vann</strong></td><td>把东西从一处住宅搬到另一处，用厢式车。<br><strong>Biex ġarrejt</strong>：为了搬运。<br><strong>l-affarijiet</strong>：物品。<br><strong>minn dar għal oħra</strong>：从一所房到另一所。<br><strong>użajt lilu</strong>：我用了它，阳性。</td></tr><tr><td>5. Biex mort Għawdex irkibt dan. — <strong>vapur</strong></td><td>去 Gozo 坐船。<br><strong>Biex mort</strong>：为了去。<br><strong>Għawdex</strong>：Gozo，戈佐岛。<br><strong>irkibt</strong>：我乘了。<br><strong>dan</strong>：这个，阳性。</td></tr><tr><td>6. Biex dort Londra rkibt din ħalli ma nikrix karozza. — <strong>tal-linja</strong></td><td>游览伦敦时坐公交，免得租车。<br><strong>Biex dort</strong>：为了游览。<br><strong>Londra</strong>：伦敦。<br><strong>rkibt din</strong>：我乘这个，阴性回指 karozza tal-linja。<br><strong>ħalli</strong>：以便。<br><strong>ma nikrix</strong>：我不用租。<br><strong>karozza</strong>：汽车。</td></tr><tr><td>7. Biex ma neħilx fit-traffiku nuża dan filgħodu. — <strong>mutur</strong></td><td>早上用摩托车，以免堵在路上。<br><strong>Biex ma neħilx</strong>：为了不被困。<br><strong>fit-traffiku</strong>：在车流／堵车中。<br><strong>nuża</strong>：我用。<br><strong>dan</strong>：这个，阳性。<br><strong>filgħodu</strong>：早晨。</td></tr><tr><td>8. Filgħodu mort dawra biha u hekk għamilt ukoll attività fiżika. — <strong>rota</strong></td><td>早上骑车兜了一圈，也做了运动。<br><strong>Filgħodu</strong>：早晨。<br><strong>mort dawra</strong>：我出去转了一圈。<br><strong>biha</strong>：用它，阴性。<br><strong>u hekk</strong>：这样也。<br><strong>għamilt ukoll</strong>：我还做了。<br><strong>attività fiżika</strong>：身体活动。</td></tr><tr><td>9. Irkibt lilha biex wasslitni eżatt id-dar. Swietni aktar flus minn tal-linja. — <strong>taxi</strong></td><td>坐出租直达家门，花钱比公交多。<br><strong>Irkibt lilha</strong>：我乘它，阴性回指此题车辆。<br><strong>biex wasslitni</strong>：让它把我送到，-ni＝我。<br><strong>eżatt id-dar</strong>：正好家门口。<br><strong>Swietni</strong>：它花了我。<br><strong>aktar flus</strong>：更多钱。<br><strong>minn tal-linja</strong>：比坐公交。</td></tr></tbody></table><p>九项各用一次。<strong>lilu / lilha / dan / din / biha</strong> 的阴阳性取决于回指的交通工具及所省略的名词，不取决于乘车人的性别。</p>',110)])])}const k=r(s,[["render",i]]);export{m as __pageData,k as default};
